insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d2000000-0000-0000-0000-000000000001', 'mrcp2', '37c9883f-19e9-4b3d-a105-6118d59ab5bb',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d2000000-0000-0000-0000-000000000001', 'A', 'Oral prednisolone 0.5-1mg/kg/day as first-line therapy', false, 'Ruled out because systemic corticosteroids carry substantially higher risk of infection, fracture and death in frail elderly patients with comorbidities, and are not superior to superpotent topical therapy for disease control.', 1),
('d2000000-0000-0000-0000-000000000001', 'B', 'Rituximab as first-line monotherapy', false, 'Ruled out because rituximab is not first-line for bullous pemphigoid; it is reserved for refractory or relapsing disease, not used ahead of a trial of topical or standard systemic therapy.', 2),
('d2000000-0000-0000-0000-000000000001', 'C', 'Dapsone monotherapy as first-line treatment', false, 'Ruled out because dapsone is not first-line for extensive bullous pemphigoid; it has a more established role in milder or localised disease or as a steroid-sparing adjunct.', 3),
('d2000000-0000-0000-0000-000000000001', 'D', 'Intravenous immunoglobulin as first-line treatment', false, 'Ruled out because IVIG is not standard first-line therapy for bullous pemphigoid; it is considered in refractory cases where conventional treatment has failed or is contraindicated.', 4),
('d2000000-0000-0000-0000-000000000001', 'E', 'Very potent topical corticosteroid (e.g. clobetasol propionate) applied to the whole body surface, rather than oral corticosteroids', true, 'Correct. Randomised trial evidence shows that whole-body application of superpotent topical corticosteroids is as effective as oral corticosteroids in controlling bullous pemphigoid, with significantly lower treatment-related mortality and morbidity, making it the preferred first-line strategy in frail elderly patients.', 5),
('d2000000-0000-0000-0000-000000000002', 'A', 'Increase the corticosteroid dose alone and plan a slower taper long-term', false, 'Ruled out because simply re-escalating corticosteroids exposes the patient to further cumulative steroid toxicity without addressing the underlying B-cell-driven autoantibody production, and is inferior to rituximab for achieving durable remission.', 1),
('d2000000-0000-0000-0000-000000000002', 'B', 'Start rituximab', true, 'Correct. Rituximab combined with a short course of corticosteroids is now recommended first-line therapy for moderate-to-severe pemphigus and is the treatment of choice on relapse during or after corticosteroid taper, given superior long-term remission and reduced cumulative steroid exposure shown in randomised trials.', 2),
('d2000000-0000-0000-0000-000000000002', 'C', 'Add azathioprine as the next steroid-sparing agent', false, 'Ruled out because although azathioprine has a historical steroid-sparing role, rituximab has superseded it as the preferred escalation given stronger efficacy evidence in relapsing/moderate-to-severe pemphigus.', 3),
('d2000000-0000-0000-0000-000000000002', 'D', 'Switch to methotrexate as monotherapy', false, 'Ruled out because methotrexate is not an established preferred agent for pemphigus relapse and would not address the B-cell-driven pathology as effectively as rituximab.', 4),
('d2000000-0000-0000-0000-000000000002', 'E', 'Add topical corticosteroids only, without changing systemic therapy', false, 'Ruled out because topical therapy alone is inadequate for a systemic relapse with new oral and cutaneous blistering and rising autoantibody titre.', 5),
('d2000000-0000-0000-0000-000000000003', 'A', 'HLA-DQ2/DQ8 typing', false, 'Ruled out because HLA typing is used to support a diagnosis of coeliac disease when other testing is equivocal, not to guide the safety of starting dapsone.', 1),
('d2000000-0000-0000-0000-000000000003', 'B', 'Anti-endomysial antibody level', false, 'Ruled out because this is a coeliac serology test used in diagnosis, already established here, and is not relevant to dapsone safety.', 2),
('d2000000-0000-0000-0000-000000000003', 'C', 'Glucose-6-phosphate dehydrogenase (G6PD) level', true, 'Correct. Dapsone causes dose-dependent haemolysis in all patients, but this is markedly more severe in G6PD deficiency, so G6PD status must be established before starting therapy.', 3),
('d2000000-0000-0000-0000-000000000003', 'D', 'Thyroid function tests alone', false, 'Ruled out because although coeliac disease and DH have associations with autoimmune thyroid disease, thyroid function is not the essential pre-dapsone safety investigation.', 4),
('d2000000-0000-0000-0000-000000000003', 'E', 'Skin prick testing', false, 'Ruled out because skin prick testing is not relevant to the diagnosis or treatment safety assessment of dermatitis herpetiformis.', 5),
('d2000000-0000-0000-0000-000000000004', 'A', 'Stop vancomycin and monitor, with additional treatment such as dapsone reserved for severe or persistent cases', true, 'Correct. Vancomycin is the drug most commonly implicated in drug-induced linear IgA bullous dermatosis, which typically resolves rapidly after withdrawal of the causative agent, so simple withdrawal with monitoring is the appropriate initial step.', 1),
('d2000000-0000-0000-0000-000000000004', 'B', 'Continue vancomycin and add high-dose oral corticosteroids', false, 'Ruled out because continuing the causative drug perpetuates the reaction; drug-induced LABD is managed primarily by withdrawal of the offending agent.', 2),
('d2000000-0000-0000-0000-000000000004', 'C', 'Switch to a different antibiotic and start rituximab immediately', false, 'Ruled out because rituximab is not required for drug-induced LABD, which typically resolves with drug withdrawal alone; this is disproportionate first-line management.', 3),
('d2000000-0000-0000-0000-000000000004', 'D', 'Continue vancomycin and add topical corticosteroids only', false, 'Ruled out for the same reason as continuing without stopping the causative drug: the eruption will not reliably settle while the culprit drug continues.', 4),
('d2000000-0000-0000-0000-000000000004', 'E', 'Arrange urgent surgical skin grafting', false, 'Ruled out because this is not a treatment for an autoimmune subepidermal blistering eruption and is not indicated here.', 5),
('d2000000-0000-0000-0000-000000000005', 'A', 'Bullous pemphigoid; first-line treatment with superpotent topical corticosteroids alone is expected to be sufficient', false, 'Ruled out because bullous pemphigoid antibodies bind the epidermal (roof) side of salt-split skin, not the dermal side, and the mechanobullous, scarring, milia-forming presentation here is atypical for BP.', 1),
('d2000000-0000-0000-0000-000000000005', 'B', 'Mucous membrane pemphigoid; management should focus on immediate ocular assessment as the primary determinant of treatment', false, 'Ruled out because mucous membrane pemphigoid characteristically involves mucosal, especially ocular, sites, which are not described here; the trauma-site scarring pattern points elsewhere.', 2),
('d2000000-0000-0000-0000-000000000005', 'C', 'Dermatitis herpetiformis; a gluten-free diet alone is the definitive treatment', false, 'Ruled out because DH shows granular IgA deposition at the dermal papillae tips, not linear IgG dermal-floor binding, and has a different clinical distribution (itchy extensor papulovesicles).', 3),
('d2000000-0000-0000-0000-000000000005', 'D', 'Epidermolysis bullosa acquisita; it is typically more treatment-resistant than bullous pemphigoid and often requires combination immunosuppression (e.g. colchicine or dapsone plus systemic corticosteroids, with rituximab reserved for refractory disease) rather than topical corticosteroids alone', true, 'Correct. Dermal (floor)-side salt-split skin binding indicates antibodies against type VII collagen in the anchoring fibrils, diagnostic of epidermolysis bullosa acquisita, which is associated with IBD, follows a mechanobullous scarring course, and is generally more resistant to standard immunosuppression than bullous pemphigoid.', 4),
('d2000000-0000-0000-0000-000000000005', 'E', 'Porphyria cutanea tarda; management should focus on venesection and hydroxychloroquine, with no role for immunosuppression', false, 'Ruled out because although PCT can cause trauma-site blistering with scarring and milia, positive IgG salt-split floor binding together with the IBD association points to EBA rather than PCT.', 5),
('d2000000-0000-0000-0000-000000000006', 'A', 'Start systemic immunosuppression with cyclophosphamide (with corticosteroids), given the high risk of blindness from progressive ocular scarring', true, 'Correct. Ocular involvement in mucous membrane pemphigoid signifies high-risk disease due to the potential for blindness from progressive scarring, and progression despite dapsone mandates prompt escalation to potent systemic immunosuppression such as cyclophosphamide.', 1),
('d2000000-0000-0000-0000-000000000006', 'B', 'Continue the current regimen and reassess in three months', false, 'Ruled out because ocular scarring is irreversible once established; delaying escalation risks permanent visual loss.', 2),
('d2000000-0000-0000-0000-000000000006', 'C', 'Escalate topical corticosteroids only', false, 'Ruled out because topical therapy has already proven insufficient to control progressive high-risk ocular disease and systemic escalation is required.', 3),
('d2000000-0000-0000-0000-000000000006', 'D', 'Add oral antihistamines for symptom control', false, 'Ruled out because antihistamines have no role in modifying the autoimmune scarring process driving symblepharon formation.', 4),
('d2000000-0000-0000-0000-000000000006', 'E', 'Refer for urgent corneal transplantation as the first step', false, 'Ruled out because surgery on actively inflamed, scarring tissue is inappropriate and would not address the underlying immune-mediated process; disease control must come first.', 5),
('d2000000-0000-0000-0000-000000000007', 'A', 'Continue carbamazepine at a reduced dose while monitoring', false, 'Ruled out because the causative drug must never be continued or rechallenged once SJS/TEN is suspected, as ongoing exposure worsens the reaction.', 1),
('d2000000-0000-0000-0000-000000000007', 'B', 'Stop carbamazepine immediately and transfer to a burns/specialist unit for supportive management (fluid/electrolyte balance, wound care, nutrition, temperature regulation, ophthalmology involvement)', true, 'Correct. Immediate withdrawal of the culprit drug is the single most important intervention in SJS/TEN, and specialist supportive care in a burns/high-dependency setting is the evidence-based mainstay of treatment given the extensive epidermal detachment and systemic derangement here.', 2),
('d2000000-0000-0000-0000-000000000007', 'C', 'Start high-dose intravenous immunoglobulin as the sole first step without stopping the drug', false, 'Ruled out because IVIG has unproven, inconsistent benefit and is not a substitute for immediate drug withdrawal and supportive care, which take priority.', 3),
('d2000000-0000-0000-0000-000000000007', 'D', 'Commence oral antihistamines and discharge with outpatient follow-up', false, 'Ruled out because this presentation with extensive epidermal detachment and abnormal SCORTEN parameters requires urgent inpatient, specialist-level supportive care, not outpatient management.', 4),
('d2000000-0000-0000-0000-000000000007', 'E', 'Apply topical corticosteroids only and observe as an outpatient', false, 'Ruled out because topical treatment alone is inadequate for extensive TEN with systemic derangement, which requires inpatient multidisciplinary supportive management.', 5),
('d2000000-0000-0000-0000-000000000008', 'A', 'Stop allopurinol and observe without steroids, as DRESS is self-limiting', false, 'Ruled out because significant organ involvement (hepatitis, eosinophilia) warrants systemic corticosteroid treatment rather than observation alone; DRESS can be severe and relapsing.', 1),
('d2000000-0000-0000-0000-000000000008', 'B', 'Continue allopurinol at a lower dose with antihistamines', false, 'Ruled out because the causative drug must be stopped, not dose-reduced, once DRESS is diagnosed.', 2),
('d2000000-0000-0000-0000-000000000008', 'C', 'Treat with topical corticosteroids alone', false, 'Ruled out because topical treatment is inadequate for systemic organ involvement (hepatitis, eosinophilia, lymphadenopathy) seen in DRESS.', 3),
('d2000000-0000-0000-0000-000000000008', 'D', 'Start antiviral therapy for HHV-6 as first-line treatment regardless of organ involvement', false, 'Ruled out because although HHV-6 reactivation is a recognised feature of DRESS, antiviral therapy is not routine first-line treatment; supportive care, drug withdrawal and immunosuppression remain central.', 4),
('d2000000-0000-0000-0000-000000000008', 'E', 'Stop allopurinol immediately and start systemic corticosteroids, with close monitoring of organ involvement given the risk of relapse over a protracted course', true, 'Correct. Systemic corticosteroids are the mainstay of treatment for significant organ involvement in DRESS after withdrawing the culprit drug, and slow tapering with monitoring is needed given the recognised risk of relapse/flare during taper.', 5),
('d2000000-0000-0000-0000-000000000009', 'A', 'Generalised pustular psoriasis (von Zumbusch); start acitretin immediately', false, 'Ruled out because the very short drug latency, absence of psoriasis history, and histology lacking psoriatic epidermal changes point away from generalised pustular psoriasis.', 1),
('d2000000-0000-0000-0000-000000000009', 'B', 'Continue the antibiotic and add topical corticosteroids', false, 'Ruled out because the causative drug should be stopped in AGEP; continuing it would perpetuate the reaction.', 2),
('d2000000-0000-0000-0000-000000000009', 'C', 'Acute generalised exanthematous pustulosis (AGEP) secondary to amoxicillin-clavulanate; stop the antibiotic and provide supportive care', true, 'Correct. The very short latency after antibiotic exposure, histology showing subcorneal pustules with papillary dermal oedema but without the epidermal changes of psoriasis, and lack of psoriasis history all support AGEP, which is managed with drug withdrawal and supportive care, usually resolving within 1-2 weeks.', 3),
('d2000000-0000-0000-0000-000000000009', 'D', 'Assume bacterial folliculitis and start further antibiotics', false, 'Ruled out because the pustules are sterile and the clinical/histological picture is consistent with a drug reaction, not infection; further antibiotics are inappropriate and unnecessary.', 4),
('d2000000-0000-0000-0000-000000000009', 'E', 'Treat as toxic epidermal necrolysis and refer for burns unit admission', false, 'Ruled out because this presentation (sterile pustules, short latency, histology without full-thickness epidermal necrosis) is characteristic of AGEP, not TEN, and does not require burns-unit-level care.', 5),
('d2000000-0000-0000-0000-000000000010', 'A', 'Sepsis alone accounts for the presentation and IV antibiotics are the priority intervention', false, 'Ruled out because although secondary infection must be excluded, the physiological derangement here is explained by loss of skin barrier function from erythroderma itself, not primarily sepsis.', 1),
('d2000000-0000-0000-0000-000000000010', 'B', 'The presentation reflects anaphylaxis and requires IM adrenaline', false, 'Ruled out because this is a chronic dermatological process (erythroderma), not an acute IgE-mediated anaphylactic reaction, and adrenaline is not indicated.', 2),
('d2000000-0000-0000-0000-000000000010', 'C', 'Hypoalbuminaemia reflects hepatic failure and the priority is liver transplant work-up', false, 'Ruled out because hypoalbuminaemia here results from cutaneous protein loss and increased metabolic demand due to erythroderma, not primary hepatic failure.', 3),
('d2000000-0000-0000-0000-000000000010', 'D', 'Loss of normal skin barrier function causes massive transepidermal fluid, heat and protein loss with increased peripheral blood flow, driving hypothermia, hypoalbuminaemia and high-output cardiac failure; management priorities include thermoregulation, careful fluid/electrolyte balance, and cardiovascular monitoring', true, $x$Correct. Erythroderma disrupts the skin's barrier and thermoregulatory functions; increased cutaneous blood flow and transepidermal water/heat/protein loss precipitate hypothermia, hypoalbuminaemia and high-output cardiac failure, particularly in elderly patients with reduced cardiac reserve, so supportive thermoregulatory and cardiovascular management is essential.$x$, 4),
('d2000000-0000-0000-0000-000000000010', 'E', 'Hypothermia indicates hypothyroidism and levothyroxine should be started empirically', false, 'Ruled out because the hypothermia is explained by erythrodermic heat loss through the skin, not thyroid dysfunction, and empirical levothyroxine is not appropriate without confirmatory testing.', 5),
('d2000000-0000-0000-0000-000000000011', 'A', 'Continue co-trimoxazole at a lower dose since previous reactions were mild', false, 'Ruled out because fixed drug eruption tends to worsen with repeated rechallenge, as seen here with new bullous change; continuing the drug risks further severe reaction.', 1),
('d2000000-0000-0000-0000-000000000011', 'B', 'Stop co-trimoxazole, document it as an allergy to avoid future rechallenge, and manage the lesion with supportive wound care', true, 'Correct. Fixed drug eruption recurs at the same site with each rechallenge and can become more severe (including bullous change) with repeated exposure, so strict future avoidance with clear allergy documentation, alongside supportive local wound care, is the appropriate management.', 2),
('d2000000-0000-0000-0000-000000000011', 'C', 'Perform oral drug provocation testing immediately to confirm the diagnosis', false, 'Ruled out because the diagnosis is already clear from the characteristic recurrent, site-specific pattern; deliberate rechallenge is unnecessary and would risk worsening the reaction.', 3),
('d2000000-0000-0000-0000-000000000011', 'D', 'Treat as bullous pemphigoid and start systemic corticosteroids', false, 'Ruled out because the recurrent, drug-triggered, single-site pattern with hyperpigmentation is characteristic of fixed drug eruption, not bullous pemphigoid, and systemic corticosteroids are not the appropriate first response.', 4),
('d2000000-0000-0000-0000-000000000011', 'E', 'Switch to trimethoprim alone, which is considered safe', false, 'Ruled out because trimethoprim can still occasionally cross-react with co-trimoxazole reactions and cannot be assumed safe without further allergy assessment; culprit identification should guide future avoidance.', 5),
('d2000000-0000-0000-0000-000000000012', 'A', 'Staphylococcal scalded skin syndrome (SSSS) secondary to exfoliative toxin-producing S. aureus; management is systemic antistaphylococcal antibiotics, supportive skin care, and treatment of the underlying infection source', true, 'Correct. The superficial subcorneal split without mucosal involvement, in the context of a staphylococcal infection source and reduced toxin clearance from renal impairment, is characteristic of SSSS, which is treated with antistaphylococcal antibiotics and supportive skin care rather than immunosuppression.', 1),
('d2000000-0000-0000-0000-000000000012', 'B', 'Toxic epidermal necrolysis; stop all medications and start high-dose systemic corticosteroids', false, 'Ruled out because TEN shows full-thickness epidermal necrosis with a subepidermal split and prominent mucosal involvement, neither of which is present here; this histology and lack of mucosal disease favour SSSS.', 2),
('d2000000-0000-0000-0000-000000000012', 'C', 'Treat as pemphigus vulgaris with rituximab', false, 'Ruled out because pemphigus shows intraepidermal acantholysis with autoantibody deposition on DIF, not a toxin-mediated subcorneal split in the context of active staphylococcal infection.', 3),
('d2000000-0000-0000-0000-000000000012', 'D', 'Manage as generalised bullous pemphigoid with topical steroids alone', false, 'Ruled out because bullous pemphigoid is a subepidermal autoimmune blistering disease with linear IgG/C3 on DIF, inconsistent with this toxin-mediated superficial split and infective context.', 4),
('d2000000-0000-0000-0000-000000000012', 'E', 'Perform skin biopsy-guided debridement under general anaesthesia as the priority intervention', false, 'Ruled out because surgical debridement is not the priority in SSSS; antistaphylococcal antibiotics and supportive skin care are the mainstay, and unnecessary anaesthesia/surgery adds risk without benefit.', 5),
('d2000000-0000-0000-0000-000000000013', 'A', 'Increase the potency of topical corticosteroids to control the eczema flare', false, 'Ruled out because increasing topical corticosteroids in active eczema herpeticum would worsen the herpetic infection and is contraindicated until it is controlled.', 1),
('d2000000-0000-0000-0000-000000000013', 'B', 'Start oral flucloxacillin alone, assuming bacterial superinfection', false, 'Ruled out because the punched-out, monomorphic haemorrhagic crusted lesions with systemic upset are characteristic of HSV infection, not primarily bacterial, and antiviral therapy should not be delayed.', 2),
('d2000000-0000-0000-0000-000000000013', 'C', 'Start IV aciclovir promptly without waiting for viral swab confirmation, alongside urgent ophthalmology assessment if periocular involvement', true, 'Correct. Eczema herpeticum is a dermatological emergency caused by widespread HSV infection on a background of disrupted skin barrier; systemic aciclovir should not be delayed pending swab confirmation given the risk of dissemination and death, and periocular involvement warrants urgent ophthalmology review.', 3),
('d2000000-0000-0000-0000-000000000013', 'D', 'Take swabs and await results before starting any antiviral treatment', false, 'Ruled out because treatment with systemic aciclovir should be started immediately on clinical suspicion, not delayed for confirmatory testing, given the risk of rapid dissemination.', 4),
('d2000000-0000-0000-0000-000000000013', 'E', 'Apply topical aciclovir cream only', false, 'Ruled out because topical antiviral therapy is inadequate for widespread, systemically unwell eczema herpeticum, which requires systemic (usually IV) aciclovir.', 5),
('d2000000-0000-0000-0000-000000000014', 'A', 'Add a second different non-sedating antihistamine at standard dose', false, 'Ruled out because combining two different antihistamines at standard dose is not the recommended escalation once up-dosing to four times a single agent has already failed; omalizumab is the next evidence-based step.', 1),
('d2000000-0000-0000-0000-000000000014', 'B', 'Switch to a first-generation sedating antihistamine at high dose', false, 'Ruled out because sedating antihistamines carry greater anticholinergic and CNS side-effect burden without proven superior efficacy, and are not the guideline-recommended next step.', 2),
('d2000000-0000-0000-0000-000000000014', 'C', 'Start long-term oral corticosteroids as maintenance therapy', false, 'Ruled out because long-term oral corticosteroids are not recommended for maintenance in chronic urticaria due to cumulative toxicity; short courses are reserved for severe exacerbations only.', 3),
('d2000000-0000-0000-0000-000000000014', 'D', 'Refer for skin prick testing to guide further antihistamine choice', false, 'Ruled out because chronic spontaneous urticaria is not typically driven by identifiable external allergens, so skin prick testing has limited value in guiding treatment escalation.', 4),
('d2000000-0000-0000-0000-000000000014', 'E', 'Add omalizumab', true, 'Correct. International urticaria guidelines recommend a stepwise approach: standard-dose non-sedating antihistamine, up-dosing to four times the licensed dose, and if still uncontrolled, addition of omalizumab as the next step, with ciclosporin reserved for omalizumab-refractory disease.', 5),
('d2000000-0000-0000-0000-000000000015', 'A', 'All three positive reactions should be treated as equally clinically significant allergens requiring avoidance', false, 'Ruled out because irritant reactions (as seen with the rubber accelerator here) do not represent true allergic sensitisation and should not be treated the same as confirmed allergic reactions.', 1),
('d2000000-0000-0000-0000-000000000015', 'B', 'The nickel reaction is the primary occupationally relevant allergen explaining her hand dermatitis', false, 'Ruled out because the weak nickel reaction is less clinically dominant here than the strong PPD reaction, which correlates directly with her occupational hair dye exposure.', 2),
('d2000000-0000-0000-0000-000000000015', 'C', 'Irritant reactions on patch testing indicate true allergic contact dermatitis', false, 'Ruled out because irritant reactions reflect non-immunological skin irritation, not IgE- or T-cell-mediated allergic sensitisation, and should not be interpreted as true allergy.', 3),
('d2000000-0000-0000-0000-000000000015', 'D', 'The PPD reaction represents a clinically relevant true allergic contact sensitivity requiring strict avoidance of PPD-containing hair dyes and cross-reacting compounds; the rubber accelerator reaction is consistent with an irritant response and does not necessarily require avoidance', true, 'Correct. True allergic reactions on patch testing (crescendo pattern, may persist to 96 hours, may vesiculate) must be distinguished from irritant reactions (fading, non-vesicular, sharply demarcated); PPD positivity in an occupationally exposed hairdresser is clinically relevant, while the fading rubber accelerator reaction is not evidence of true sensitisation.', 4),
('d2000000-0000-0000-0000-000000000015', 'E', 'Patch testing should be abandoned since the results are inconsistent', false, 'Ruled out because the results are not inconsistent; they can be correctly interpreted by distinguishing true allergic from irritant reaction patterns, which remains clinically useful.', 5),
('d2000000-0000-0000-0000-000000000016', 'A', 'No baseline investigations are required as JAK inhibitors have a favourable safety profile in all patients', false, 'Ruled out because JAK inhibitors carry recognised class-wide safety signals requiring baseline screening, not an assumption of universal safety.', 1),
('d2000000-0000-0000-0000-000000000016', 'B', 'Only a pregnancy test is required before initiation', false, 'Ruled out because although pregnancy status is relevant, it is not the only necessary baseline assessment; infection and cardiovascular/thromboembolic risk screening are also essential.', 2),
('d2000000-0000-0000-0000-000000000016', 'C', 'Baseline eye examination is mandatory before every JAK inhibitor but no other screening is needed', false, 'Ruled out because routine baseline ophthalmological examination is not a standard requirement for JAK inhibitors in atopic dermatitis, whereas infection and cardiovascular screening are.', 3),
('d2000000-0000-0000-0000-000000000016', 'D', 'Renal function need not be reassessed given prior ciclosporin-induced impairment has necessarily resolved', false, 'Ruled out because renal function should be reassessed as a new baseline rather than assumed to have normalised after stopping a nephrotoxic drug.', 4),
('d2000000-0000-0000-0000-000000000016', 'E', 'Screen for active or latent infection (including tuberculosis and viral hepatitis), assess cardiovascular risk factors and prior venous thromboembolism, and discuss the increased risk of major adverse cardiovascular events, malignancy and thromboembolism associated with this drug class', true, 'Correct. Oral JAK inhibitors carry a class-wide boxed warning for increased risk of major adverse cardiovascular events, venous thromboembolism, malignancy and serious infection, requiring baseline infection screening and cardiovascular/thromboembolic risk assessment before initiation.', 5),
('d2000000-0000-0000-0000-000000000017', 'A', 'IM adrenaline as first-line treatment', false, 'Ruled out because HAE attacks are not mast-cell/histamine-mediated and characteristically do not respond to adrenaline, as demonstrated by the lack of response during her previous attendance.', 1),
('d2000000-0000-0000-0000-000000000017', 'B', 'IV C1 esterase inhibitor concentrate (or icatibant, a bradykinin B2 receptor antagonist)', true, 'Correct. Hereditary angioedema is a bradykinin-mediated, not histamine-mediated, process, so first-line acute treatment is C1 esterase inhibitor concentrate, icatibant, or (where available) ecallantide, none of which act via antihistamine or adrenergic pathways.', 2),
('d2000000-0000-0000-0000-000000000017', 'C', 'High-dose oral corticosteroids', false, 'Ruled out because corticosteroids target inflammatory/allergic pathways, not the bradykinin-mediated mechanism of HAE, and are not effective for acute attacks.', 3),
('d2000000-0000-0000-0000-000000000017', 'D', 'IV antihistamines at higher dose', false, 'Ruled out because antihistamines act on histamine receptors and have no effect on the bradykinin-driven pathophysiology of HAE.', 4),
('d2000000-0000-0000-0000-000000000017', 'E', 'Omalizumab', false, 'Ruled out because omalizumab targets IgE-mediated mast cell pathways relevant to chronic urticaria, not the complement/bradykinin pathway underlying hereditary angioedema.', 5),
('d2000000-0000-0000-0000-000000000018', 'A', 'Chronic spontaneous urticaria; manage with antihistamine dose escalation as per the standard CSU pathway', false, 'Ruled out because the prolonged individual lesion duration, residual bruising, burning quality, and biopsy findings are atypical for ordinary urticaria and instead indicate vasculitis, which does not respond reliably to antihistamines alone.', 1),
('d2000000-0000-0000-0000-000000000018', 'B', 'Cutaneous small vessel vasculitis unrelated to urticaria, requiring no further systemic work-up', false, 'Ruled out because the hypocomplementaemic pattern with systemic features (arthralgia, proteinuria) raises significant concern for an associated systemic disease requiring further investigation.', 2),
('d2000000-0000-0000-0000-000000000018', 'C', 'Hypocomplementaemic urticarial vasculitis; investigate for an underlying systemic disease (e.g. SLE) and consider systemic immunosuppression rather than standard antihistamine therapy alone', true, 'Correct. Lesions lasting more than 24 hours with residual pigmentation, burning rather than itch, systemic features, and biopsy-confirmed leukocytoclastic vasculitis with hypocomplementaemia indicate urticarial vasculitis, which (especially the hypocomplementaemic form) is associated with systemic disease such as SLE and requires broader work-up and systemic anti-inflammatory treatment.', 3),
('d2000000-0000-0000-0000-000000000018', 'D', 'Reassure that this is a self-limiting condition requiring no investigation', false, 'Ruled out because hypocomplementaemic urticarial vasculitis carries risk of significant systemic (including renal) involvement and requires active investigation and management, not simple reassurance.', 4),
('d2000000-0000-0000-0000-000000000018', 'E', 'Treat with topical corticosteroids alone', false, 'Ruled out because topical therapy does not address the systemic vasculitic process or any underlying systemic disease driving it.', 5),
('d2000000-0000-0000-0000-000000000019', 'A', 'Pregnancy testing is only required once before starting treatment', false, 'Ruled out because pregnancy testing must continue monthly throughout treatment (and after stopping, as advised), not just at baseline, given the ongoing teratogenic risk with each cycle.', 1),
('d2000000-0000-0000-0000-000000000019', 'B', 'Liver function and lipid monitoring are not necessary once baseline results are normal', false, 'Ruled out because periodic monitoring should continue during treatment, as transaminitis and hypertriglyceridaemia/hypercholesterolaemia can develop after treatment initiation.', 2),
('d2000000-0000-0000-0000-000000000019', 'C', 'Contraception can be safely stopped once acne improves during the course of treatment', false, 'Ruled out because effective contraception must be maintained for the entire treatment duration (and for a period afterward as advised) regardless of clinical improvement, given ongoing teratogenic risk.', 3),
('d2000000-0000-0000-0000-000000000019', 'D', 'Monthly pregnancy tests throughout treatment, alongside baseline and periodic monitoring of liver function and lipid profile, and ongoing assessment of mood/mental health', true, $x$Correct. The Pregnancy Prevention Programme mandates monthly pregnancy testing throughout treatment given isotretinoin's potent teratogenicity; baseline and periodic LFTs and fasting lipids are recommended given the risk of transaminitis and dyslipidaemia; and mood/mental health should be monitored throughout given ongoing guidance on this association.$x$, 4),
('d2000000-0000-0000-0000-000000000019', 'E', 'Mental health screening is not required as isotretinoin has no recognised psychiatric association', false, 'Ruled out because although the causal link with depression/suicidality remains debated, current guidance recommends monitoring mood and mental health throughout treatment.', 5),
('d2000000-0000-0000-0000-000000000020', 'A', 'Start adalimumab', true, 'Correct. Adalimumab is licensed and recommended as the next step for moderate-to-severe hidradenitis suppurativa that has failed conventional systemic antibiotic therapy, targeting the underlying TNF-alpha-driven inflammatory process.', 1),
('d2000000-0000-0000-0000-000000000020', 'B', 'Repeat the same antibiotic combination for a further prolonged course', false, 'Ruled out because the patient has already failed an adequate trial of combination antibiotics; simply repeating the same regimen is unlikely to achieve further benefit and delays effective escalation.', 2),
('d2000000-0000-0000-0000-000000000020', 'C', 'Refer directly for wide surgical excision as the only remaining option', false, 'Ruled out because biologic therapy is an appropriate next step for active inflammatory disease before considering wide excision, which is more typically reserved for localised, fibrotic or sinus tract disease.', 3),
('d2000000-0000-0000-0000-000000000020', 'D', 'Start oral isotretinoin as the most effective next step', false, 'Ruled out because isotretinoin has limited and inconsistent efficacy in HS (unlike in acne) and is not considered an appropriate next-line therapy for treatment-resistant disease.', 4),
('d2000000-0000-0000-0000-000000000020', 'E', 'Add topical corticosteroids to the affected areas', false, 'Ruled out because topical corticosteroids have no established role in treating the deep follicular occlusion and inflammatory sinus tract process of hidradenitis suppurativa.', 5),
('d2000000-0000-0000-0000-000000000021', 'A', 'Start oral corticosteroids first, with isotretinoin introduced at a low dose only after the acute inflammatory flare is controlled', true, 'Correct. Acne fulminans is an acute, severe, ulcerative variant of acne with systemic inflammatory features; starting isotretinoin without prior corticosteroid control can precipitate a severe flare, so oral corticosteroids should be commenced first, with isotretinoin introduced cautiously afterward in overlap.', 1),
('d2000000-0000-0000-0000-000000000021', 'B', 'Start high-dose isotretinoin immediately as monotherapy', false, 'Ruled out because starting isotretinoin without preceding corticosteroid control risks precipitating a severe worsening of the inflammatory flare in acne fulminans.', 2),
('d2000000-0000-0000-0000-000000000021', 'C', 'Start oral antibiotics alone without steroids or isotretinoin', false, 'Ruled out because the systemic inflammatory features (fever, arthralgia, raised inflammatory markers) reflect an immune-mediated process requiring corticosteroids, not simply antibiotic therapy.', 3),
('d2000000-0000-0000-0000-000000000021', 'D', 'Give topical corticosteroids to affected lesions only', false, 'Ruled out because topical treatment alone is inadequate for the systemic inflammatory features and extensive ulcerative disease seen in acne fulminans.', 4),
('d2000000-0000-0000-0000-000000000021', 'E', 'Admit solely for IV antibiotics assuming bacterial cellulitis', false, 'Ruled out because this presentation reflects an immune-mediated inflammatory reaction (acne fulminans) rather than primary bacterial cellulitis, so antibiotics alone would not address the underlying process.', 5),
('d2000000-0000-0000-0000-000000000022', 'A', 'Increase the dose of oral doxycycline as monotherapy, expecting it to reverse established phymatous change', false, 'Ruled out because antibiotics target the inflammatory papulopustular component of rosacea and have limited effect on established sebaceous hyperplasia and fibrosis in phymatous change.', 1),
('d2000000-0000-0000-0000-000000000022', 'B', 'Long-term topical corticosteroids should be used to reduce nasal thickening', false, 'Ruled out because long-term topical or systemic corticosteroids can worsen rosacea and may precipitate steroid-induced rosacea, so they should be avoided.', 2),
('d2000000-0000-0000-0000-000000000022', 'C', 'Oral isotretinoin is contraindicated in rosacea and should be avoided', false, 'Ruled out because low-dose isotretinoin is a recognised, useful option for phymatous rosacea by reducing sebaceous gland activity.', 3),
('d2000000-0000-0000-0000-000000000022', 'D', 'Low-dose oral isotretinoin can help reduce sebaceous gland hyperplasia in phymatous rosacea, though established rhinophyma often ultimately requires surgical or ablative laser recontouring for definitive correction', true, 'Correct. Phymatous rosacea reflects sebaceous gland hyperplasia and fibrosis that responds poorly to antibiotics; low-dose isotretinoin can reduce sebaceous activity, but established architectural change is often best addressed with surgical or laser recontouring.', 4),
('d2000000-0000-0000-0000-000000000022', 'E', 'Reassurance only is appropriate, as no treatment is available for phymatous change', false, 'Ruled out because effective options exist (low-dose isotretinoin for the inflammatory/glandular component, and surgical/laser recontouring for established architectural change).', 5),
('d2000000-0000-0000-0000-000000000023', 'A', 'Switch to an even more potent topical corticosteroid to control the rebound flare', false, 'Ruled out because escalating corticosteroid potency perpetuates the underlying problem and delays resolution of perioral dermatitis.', 1),
('d2000000-0000-0000-0000-000000000023', 'B', 'Continue the current topical steroid indefinitely at a lower frequency', false, 'Ruled out because continued topical corticosteroid use, even reduced, sustains the process driving perioral dermatitis rather than resolving it.', 2),
('d2000000-0000-0000-0000-000000000023', 'C', 'Gradually wean and stop the topical corticosteroid and start oral tetracycline (or topical metronidazole/erythromycin if tetracyclines are contraindicated)', true, 'Correct. Abrupt cessation of topical corticosteroids in perioral dermatitis causes rebound worsening, so a gradual weaning strategy alongside oral tetracyclines (or an appropriate alternative) is the standard approach.', 3),
('d2000000-0000-0000-0000-000000000023', 'D', 'Treat as bacterial impetigo with topical mupirocin alone', false, 'Ruled out because the clinical pattern (perioral papulopustules sparing the vermilion border, related to topical steroid use) is characteristic of perioral dermatitis, not impetigo.', 4),
('d2000000-0000-0000-0000-000000000023', 'E', 'Start oral isotretinoin as first-line therapy', false, 'Ruled out because oral tetracyclines are the standard first-line systemic treatment for perioral dermatitis; isotretinoin is not the first-line approach.', 5),
('d2000000-0000-0000-0000-000000000024', 'A', 'Start oral isotretinoin given the severity of the flare', false, 'Ruled out because isotretinoin is a potent teratogen and absolutely contraindicated in pregnancy.', 1),
('d2000000-0000-0000-0000-000000000024', 'B', 'Start oral doxycycline as first-line antibiotic', false, 'Ruled out because tetracyclines including doxycycline are contraindicated in pregnancy due to fetal teeth discolouration and effects on bone growth.', 2),
('d2000000-0000-0000-0000-000000000024', 'C', 'Commence oral tetracycline, as it is considered pregnancy category safe', false, 'Ruled out because tetracyclines are not safe in pregnancy and are contraindicated for the reasons above.', 3),
('d2000000-0000-0000-0000-000000000024', 'D', 'Treat with topical retinoids as first-line therapy', false, 'Ruled out because topical retinoids also carry teratogenic concern and are generally avoided in pregnancy; they are also not appropriate first-line therapy for this severity of inflammatory flare.', 4),
('d2000000-0000-0000-0000-000000000024', 'E', 'A short course of oral corticosteroids to control the acute inflammatory flare, with careful selection of pregnancy-safe topical or systemic agents (e.g. azelaic acid, or erythromycin if antibiotic therapy is needed), avoiding isotretinoin and tetracyclines', true, 'Correct. Isotretinoin and tetracyclines are both contraindicated in pregnancy; oral corticosteroids can be used cautiously for short-term control of severe inflammatory flares when benefit outweighs risk, alongside pregnancy-safe agents such as azelaic acid or erythromycin.', 5),
('d2000000-0000-0000-0000-000000000025', 'A', 'Repeat a course of the same intralesional corticosteroid at a higher dose as the most effective next option', false, 'Ruled out because intralesional corticosteroids have already failed and are impractical for the entire scalp in alopecia totalis; a systemic option with proven efficacy in this severity is more appropriate.', 1),
('d2000000-0000-0000-0000-000000000025', 'B', 'Oral JAK inhibitor (e.g. baricitinib), now licensed for severe alopecia areata, following discussion of associated risks and required baseline screening', true, 'Correct. Oral JAK inhibitors have demonstrated efficacy in regrowing hair in moderate-to-severe alopecia areata refractory to topical/intralesional treatment and contact immunotherapy, and are now a recognised treatment option in this setting, requiring baseline infection and cardiovascular/thromboembolic risk screening.', 2),
('d2000000-0000-0000-0000-000000000025', 'C', 'Reassure that no further treatment options exist beyond wigs', false, 'Ruled out because oral JAK inhibitors represent an effective, evidence-based option for severe refractory alopecia areata that should be discussed before concluding no further treatment exists.', 3),
('d2000000-0000-0000-0000-000000000025', 'D', 'Start oral isotretinoin as an evidence-based treatment for alopecia areata', false, 'Ruled out because isotretinoin has no established role in treating alopecia areata, which is an autoimmune hair loss condition unrelated to sebaceous gland activity.', 4),
('d2000000-0000-0000-0000-000000000025', 'E', 'Recommend hair transplant surgery as the next step', false, 'Ruled out because hair transplantation is not appropriate in active alopecia areata, as it is an autoimmune process that can affect transplanted follicles, and has no role until disease activity is stable.', 5),
('d2000000-0000-0000-0000-000000000026', 'A', 'Finasteride has no recognised sexual side effects and this need not be discussed', false, 'Ruled out because sexual dysfunction is a well-recognised and clinically important side effect that must be part of informed consent discussion.', 1),
('d2000000-0000-0000-0000-000000000026', 'B', 'Finasteride is safe for use by pregnant partners with no precautions needed', false, 'Ruled out because finasteride tablets carry teratogenic risk to a male fetus if handled by a pregnant woman (crushed/broken tablets), so precautions are needed.', 2),
('d2000000-0000-0000-0000-000000000026', 'C', 'Risk of sexual side effects (reduced libido, erectile dysfunction, ejaculatory dysfunction), which may rarely persist after stopping the drug, and the need to avoid handling crushed/broken tablets if his partner is or may become pregnant', true, 'Correct. Finasteride, a 5-alpha reductase inhibitor, is recognised to cause sexual side effects that usually resolve on stopping but have rarely been reported to persist; tablets should not be handled by women who are or may become pregnant due to teratogenic risk to a male fetus.', 3),
('d2000000-0000-0000-0000-000000000026', 'D', 'Finasteride is known to cause irreversible hepatotoxicity requiring routine LFT monitoring', false, 'Ruled out because finasteride is not associated with a well-established hepatotoxicity monitoring requirement in the way isotretinoin is; routine LFT monitoring is not a standard requirement.', 4),
('d2000000-0000-0000-0000-000000000026', 'E', 'Finasteride is contraindicated in all men under 40 with androgenetic alopecia', false, 'Ruled out because finasteride is licensed and commonly used in younger men with androgenetic alopecia; age under 40 is not a contraindication.', 5),
('d2000000-0000-0000-0000-000000000027', 'A', 'Treatment can be deferred until hair loss is extensive since the condition often resolves spontaneously', false, 'Ruled out because delaying treatment allows ongoing irreversible follicular destruction; early treatment is important precisely because scarring alopecia does not reliably resolve spontaneously without intervention.', 1),
('d2000000-0000-0000-0000-000000000027', 'B', 'Early, aggressive anti-inflammatory treatment (topical/intralesional corticosteroids, and systemic agents such as hydroxychloroquine or oral immunosuppressants for progressive disease) is required to halt disease activity, because established scarring and follicular loss are irreversible', true, 'Correct. Lichen planopilaris is a primary scarring alopecia where active inflammation irreversibly destroys the follicular stem cell niche, so early disease suppression is critical to prevent further permanent hair loss, even though treatment cannot regrow already-scarred areas.', 2),
('d2000000-0000-0000-0000-000000000027', 'C', 'Hair transplantation should be offered as first-line treatment while inflammation is still active', false, 'Ruled out because transplantation into actively inflamed scalp risks failure of the transplanted follicles and should only be considered once disease activity is stable/quiescent.', 3),
('d2000000-0000-0000-0000-000000000027', 'D', 'Minoxidil alone is sufficient as first-line therapy', false, 'Ruled out because minoxidil promotes hair growth in non-scarring alopecias but does not address the underlying inflammatory destruction of follicles in lichen planopilaris.', 4),
('d2000000-0000-0000-0000-000000000027', 'E', 'Reassurance only is appropriate as there is no effective treatment', false, 'Ruled out because effective anti-inflammatory treatments exist to halt disease progression, and early intervention is important given the irreversibility of established scarring.', 5),
('d2000000-0000-0000-0000-000000000028', 'A', 'Proceed directly to biologic therapy without further nail investigation, as the clinical appearance is diagnostic', false, 'Ruled out because clinical overlap between nail psoriasis and onychomycosis is significant, and missing a concurrent fungal infection before starting immunosuppressive biologic therapy risks worsening the fungal infection.', 1),
('d2000000-0000-0000-0000-000000000028', 'B', 'Treat empirically with oral antifungal therapy alone assuming onychomycosis without biologic escalation', false, 'Ruled out because this assumes fungal infection without confirmation and ignores the possibility that psoriasis is the dominant or sole process warranting biologic escalation; mycology should guide the decision rather than empirical treatment alone.', 2),
('d2000000-0000-0000-0000-000000000028', 'C', 'Perform nail bed biopsy as the mandatory first investigation in all cases', false, 'Ruled out because nail clippings/scrapings for mycology are the appropriate first-line, less invasive investigation; biopsy is reserved for diagnostic uncertainty after simpler testing.', 3),
('d2000000-0000-0000-0000-000000000028', 'D', 'Recommend nail avulsion surgery as the initial management step', false, 'Ruled out because surgical avulsion is not an appropriate initial step before establishing the diagnosis with mycological testing.', 4),
('d2000000-0000-0000-0000-000000000028', 'E', 'Take nail clippings/scrapings for mycology (microscopy and culture, or PCR) to exclude concomitant onychomycosis', true, 'Correct. Nail psoriasis and onychomycosis can closely mimic one another and frequently coexist, as psoriatic nail dystrophy predisposes to fungal superinfection; mycological confirmation or exclusion should be sought before committing to systemic immunosuppressive/biologic therapy targeted at psoriasis.', 5),
('d2000000-0000-0000-0000-000000000029', 'A', 'Botulinum toxin A injections to the axillae', true, 'Correct. The stepwise management ladder for primary focal hyperhidrosis progresses from topical aluminium salts to botulinum toxin A injections if topical treatment fails, particularly effective and licensed for axillary hyperhidrosis, before considering oral anticholinergics or further procedural options.', 1),
('d2000000-0000-0000-0000-000000000029', 'B', 'Proceed directly to endoscopic thoracic sympathectomy', false, 'Ruled out because sympathectomy carries significant risk of compensatory hyperhidrosis and is generally reserved as a later/last resort, not an early option after topical treatment failure.', 2),
('d2000000-0000-0000-0000-000000000029', 'C', 'Start oral glycopyrrolate as first escalation', false, 'Ruled out because oral anticholinergics are typically considered after botulinum toxin has been tried or is unsuitable, given their systemic side-effect burden.', 3),
('d2000000-0000-0000-0000-000000000029', 'D', 'Refer for axillary tissue excision surgery', false, 'Ruled out because surgical excision is a more invasive option generally reserved for cases refractory to less invasive treatments such as botulinum toxin.', 4),
('d2000000-0000-0000-0000-000000000029', 'E', 'Recommend iontophoresis, which is primarily indicated for palmoplantar rather than axillary hyperhidrosis', false, 'Ruled out because iontophoresis is most useful for palmoplantar hyperhidrosis, where access and technique make it more practical, rather than for axillary disease.', 5),
('d2000000-0000-0000-0000-000000000030', 'A', 'Both processes have an identical timeframe and mechanism, differing only in cause', false, 'Ruled out because the two processes act on different phases of the hair cycle (anagen versus telogen) and therefore have distinctly different latencies before hair loss becomes apparent.', 1),
('d2000000-0000-0000-0000-000000000030', 'B', 'Anagen effluvium is always delayed by several months while telogen effluvium is immediate', false, 'Ruled out because this reverses the actual pattern: anagen effluvium is rapid (days to weeks) while telogen effluvium is delayed (around 2-3 months).', 2),
('d2000000-0000-0000-0000-000000000030', 'C', 'The timing differences are coincidental and unrelated to the hair growth cycle', false, 'Ruled out because the differing latencies are directly explained by the underlying hair cycle physiology, not coincidence.', 3),
('d2000000-0000-0000-0000-000000000030', 'D', 'Chemotherapy causes anagen effluvium, with abrupt cessation of mitotic activity in the actively growing follicle causing hair loss within days to weeks, whereas physiological stress/illness precipitates telogen effluvium, where hairs shift into the resting phase and shed around 2-3 months later', true, 'Correct. Anagen effluvium (from cytotoxic chemotherapy) interrupts hair matrix mitosis directly, causing rapid loss within days to a couple of weeks, while telogen effluvium follows a triggering event that shifts follicles into telogen, which lasts around three months before the hair sheds, explaining the delayed presentation in her friend.', 4),
('d2000000-0000-0000-0000-000000000030', 'E', 'Telogen effluvium reflects permanent, scarring follicular damage while anagen effluvium is always reversible without any latency', false, 'Ruled out because telogen effluvium is typically non-scarring and reversible, and anagen effluvium (though rapid in onset) is also usually reversible once the causative insult is removed.', 5),
('d2000000-0000-0000-0000-000000000031', 'A', 'Treat with topical aciclovir cream to the rash alone', false, 'Ruled out because topical antivirals are inadequate for herpes zoster; systemic therapy is required to reduce viral replication and the risk of ocular and neurological complications.', 1),
('d2000000-0000-0000-0000-000000000031', 'B', 'Reassure and review only if visual symptoms develop', false, $x$Ruled out because Hutchinson's sign predicts ocular involvement even before visual symptoms appear, so urgent proactive ophthalmology review is required now, not deferred.$x$, 2),
('d2000000-0000-0000-0000-000000000031', 'C', 'Delay antiviral treatment until ophthalmology has assessed the eye', false, 'Ruled out because systemic antiviral therapy should be started promptly alongside, not delayed pending, ophthalmology assessment, since early treatment improves outcomes.', 3),
('d2000000-0000-0000-0000-000000000031', 'D', 'Treat with oral antibiotics for presumed bacterial cellulitis', false, 'Ruled out because the vesicular, dermatomal pattern is characteristic of herpes zoster, not bacterial cellulitis, and antiviral rather than antibiotic therapy is indicated.', 4),
('d2000000-0000-0000-0000-000000000031', 'E', $x$Start oral (or IV if severe/immunocompromised) high-dose aciclovir promptly and arrange urgent ophthalmology review given the Hutchinson's sign$x$, true, $x$Correct. Hutchinson's sign (vesicles on the tip, side or root of the nose, reflecting nasociliary nerve involvement) strongly predicts ocular involvement in herpes zoster ophthalmicus, so urgent ophthalmology referral is needed regardless of current visual symptoms, alongside prompt systemic antiviral therapy to reduce the risk of ocular complications.$x$, 5),
('d2000000-0000-0000-0000-000000000032', 'A', 'Start IV antibiotics alone and observe response over 24-48 hours before considering surgery', false, 'Ruled out because delaying surgical source control while awaiting a response to antibiotics alone significantly increases mortality in necrotising fasciitis.', 1),
('d2000000-0000-0000-0000-000000000032', 'B', 'Obtain an MRI to confirm the diagnosis before proceeding to theatre', false, 'Ruled out because imaging should not delay surgical exploration when clinical suspicion is high, as necrotising fasciitis progresses rapidly and delay is harmful.', 2),
('d2000000-0000-0000-0000-000000000032', 'C', 'Manage as simple cellulitis with oral antibiotics and outpatient follow-up', false, 'Ruled out because the systemic toxicity, pain out of proportion, bullae and gas on imaging indicate a surgical emergency, not simple cellulitis manageable as an outpatient.', 3),
('d2000000-0000-0000-0000-000000000032', 'D', 'Urgent surgical exploration and debridement, alongside broad-spectrum IV antibiotics and haemodynamic resuscitation', true, 'Correct. Necrotising fasciitis is a surgical emergency; clinical suspicion should prompt immediate surgical debridement without waiting for definitive imaging or deteriorating further on antibiotics alone, as delay significantly increases mortality; surgery is the single most important determinant of survival.', 4),
('d2000000-0000-0000-0000-000000000032', 'E', 'Apply topical antiseptic dressings and review in 24 hours', false, 'Ruled out because this delay would be catastrophic in necrotising fasciitis, which requires immediate surgical intervention.', 5),
('d2000000-0000-0000-0000-000000000033', 'A', 'Single application of topical permethrin alone, as used for ordinary scabies', false, 'Ruled out because standard single-application treatment is inadequate for crusted scabies, where the thick keratotic crust shields mites and combination, repeated treatment is required.', 1),
('d2000000-0000-0000-0000-000000000033', 'B', 'Oral ivermectin as a single dose only, with no topical treatment or isolation needed', false, 'Ruled out because single-dose ivermectin alone is insufficient for the very high mite burden of crusted scabies, and isolation precautions are essential given its high infectivity.', 2),
('d2000000-0000-0000-0000-000000000033', 'C', 'Combination treatment with oral ivermectin (multiple doses) and topical permethrin, alongside strict isolation/barrier precautions given the very high mite burden and infectivity', true, 'Correct. Crusted (Norwegian) scabies has an enormous mite burden and is highly contagious, requiring combination and often repeated dosing (oral ivermectin plus topical scabicide applied to the whole body) because the thick crust can shield mites from single-dose or topical-only treatment, alongside strict isolation to prevent outbreaks.', 3),
('d2000000-0000-0000-0000-000000000033', 'D', 'Reassurance and emollients only, since itching is minimal', false, 'Ruled out because minimal itching in crusted scabies reflects blunted immune response, not lower mite burden, which is in fact very high; active antiparasitic treatment is required.', 4),
('d2000000-0000-0000-0000-000000000033', 'E', 'Treat as psoriasis with topical corticosteroids given the hyperkeratotic plaques', false, 'Ruled out because microscopy has already confirmed mites and eggs, establishing crusted scabies as the diagnosis; topical corticosteroids would worsen the infestation by further impairing local immune response.', 5),
('d2000000-0000-0000-0000-000000000034', 'A', 'This represents a typical response to correctly treated eczema and the current management should continue unchanged', false, 'Ruled out because loss of the well-demarcated annular border with spreading, poorly defined erythema after prolonged steroid use is atypical for improving eczema and should prompt reconsideration of the diagnosis.', 1),
('d2000000-0000-0000-0000-000000000034', 'B', 'Tinea incognito, a dermatophyte infection modified and partially masked by inappropriate topical corticosteroid use; management is to stop the corticosteroid and start an appropriate topical or oral antifungal, guided by mycology', true, 'Correct. Tinea incognito results from application of topical corticosteroids to an unrecognised dermatophyte infection, which suppresses the typical inflammatory features and well-demarcated annular border, allowing the fungal infection to spread more extensively while symptoms are temporarily masked; management requires stopping the steroid and starting an antifungal.', 2),
('d2000000-0000-0000-0000-000000000034', 'C', 'The presentation indicates steroid-induced atrophy, requiring an even more potent corticosteroid to control ongoing inflammation', false, 'Ruled out because escalating corticosteroid potency would further mask and worsen an underlying fungal infection rather than treat it.', 3),
('d2000000-0000-0000-0000-000000000034', 'D', 'This is consistent with treatment failure of eczema and warrants oral corticosteroids', false, 'Ruled out because the correct next step is to investigate for an alternative diagnosis (tinea incognito) via mycology, not escalate to systemic corticosteroids, which would worsen a fungal infection.', 4),
('d2000000-0000-0000-0000-000000000034', 'E', 'The findings suggest allergic contact dermatitis to the topical steroid itself, requiring patch testing before any other action', false, 'Ruled out because the clinical evolution (spreading, loss of typical annular border after prolonged topical steroid use in the groin) is most consistent with tinea incognito, and mycology should be prioritised over patch testing.', 5),
('d2000000-0000-0000-0000-000000000035', 'A', 'Refer to a specialist tropical medicine/infectious diseases centre for species-directed systemic treatment, given the risk of mucocutaneous dissemination with this Leishmania species', true, 'Correct. Species identification is critical in cutaneous leishmaniasis because certain New World species carry a significant risk of mucocutaneous spread and require systemic (rather than purely topical/local) treatment to reduce this risk, making specialist referral for species-directed treatment essential.', 1),
('d2000000-0000-0000-0000-000000000035', 'B', 'Manage with topical paromomycin alone regardless of species identified', false, 'Ruled out because topical therapy alone is inadequate for species with recognised risk of mucocutaneous dissemination, which require systemic treatment.', 2),
('d2000000-0000-0000-0000-000000000035', 'C', 'Treat empirically with a further course of oral antibiotics for presumed resistant bacterial infection', false, 'Ruled out because the diagnosis has already been confirmed as cutaneous leishmaniasis by biopsy and PCR/culture; further antibacterial treatment is not appropriate.', 3),
('d2000000-0000-0000-0000-000000000035', 'D', 'Reassure that spontaneous resolution without treatment is expected within days', false, 'Ruled out because species associated with mucocutaneous spread require active systemic treatment to reduce the risk of dissemination, not expectant management.', 4),
('d2000000-0000-0000-0000-000000000035', 'E', 'Perform wide surgical excision as definitive first-line management', false, 'Ruled out because surgical excision is not standard first-line management for cutaneous leishmaniasis, particularly with species carrying risk of mucocutaneous spread, which require systemic antileishmanial therapy.', 5),
('d2000000-0000-0000-0000-000000000036', 'A', $x$An anti-TNF agent or an IL-23 inhibitor would be appropriate, as both have efficacy in Crohn's disease; IL-17 inhibitors should be avoided as they can cause new-onset or exacerbation of inflammatory bowel disease$x$, true, $x$Correct. Anti-TNF agents and IL-23 inhibitors have established efficacy in both psoriasis and Crohn's disease, making them preferred choices, whereas IL-17 inhibitors are associated with new-onset or worsening IBD and should generally be avoided in patients with known Crohn's disease.$x$, 1),
('d2000000-0000-0000-0000-000000000036', 'B', $x$An IL-17 inhibitor is the most appropriate first choice given its high efficacy in skin disease, with no relevance of his Crohn's disease to this decision$x$, false, $x$Ruled out because IL-17 inhibitors carry a recognised risk of inducing or worsening inflammatory bowel disease and should be avoided in a patient with known Crohn's disease.$x$, 2),
('d2000000-0000-0000-0000-000000000036', 'C', 'Any biologic class is equally appropriate and comorbidity need not influence the choice', false, 'Ruled out because comorbidities such as IBD critically influence biologic selection in psoriasis, favouring anti-TNF or IL-23 inhibitors over IL-17 inhibitors in this patient.', 3),
('d2000000-0000-0000-0000-000000000036', 'D', 'IL-23 inhibitors are contraindicated in inflammatory bowel disease and should be avoided', false, $x$Ruled out because IL-23 inhibitors have demonstrated efficacy in Crohn's disease and are an appropriate, not contraindicated, choice in this context.$x$, 4),
('d2000000-0000-0000-0000-000000000036', 'E', $x$Anti-TNF agents should be avoided in Crohn's disease due to risk of exacerbation$x$, false, $x$Ruled out because anti-TNF agents are an established, effective treatment for Crohn's disease, not a risk factor for exacerbating it.$x$, 5),
('d2000000-0000-0000-0000-000000000037', 'A', 'Restart oral corticosteroids at an even higher dose as monotherapy long-term', false, 'Ruled out because corticosteroids are a recognised precipitant of GPP flares when withdrawn abruptly, and are not the definitive long-term systemic treatment of choice for this condition.', 1),
('d2000000-0000-0000-0000-000000000037', 'B', 'Admit for inpatient management with supportive care and urgent systemic therapy (e.g. a biologic, acitretin or ciclosporin), avoiding further abrupt corticosteroid withdrawal', true, 'Correct. Generalised pustular psoriasis is a dermatological emergency with significant risk of systemic complications (sepsis, high-output cardiac failure, electrolyte disturbance) requiring inpatient multidisciplinary management with fluid/electrolyte correction and rapid-acting systemic therapy, while avoiding further corticosteroid withdrawal, which is a recognised precipitant.', 2),
('d2000000-0000-0000-0000-000000000037', 'C', 'Discharge with topical corticosteroids and outpatient dermatology follow-up', false, 'Ruled out because this presentation with systemic instability (tachycardia, hypotension, hypocalcaemia) requires urgent inpatient management, not outpatient follow-up.', 3),
('d2000000-0000-0000-0000-000000000037', 'D', 'Treat with oral antibiotics alone, assuming staphylococcal folliculitis', false, 'Ruled out because the pustules are sterile and this represents an inflammatory flare of psoriasis, not a primary bacterial infection.', 4),
('d2000000-0000-0000-0000-000000000037', 'E', 'Manage as an isolated dermatological issue without inpatient systemic assessment', false, 'Ruled out because GPP carries significant risk of systemic complications requiring full inpatient assessment and multidisciplinary supportive care, not isolated dermatological management.', 5),
('d2000000-0000-0000-0000-000000000038', 'A', 'Methotrexate dose escalation alone is the most appropriate next step for axial symptoms', false, 'Ruled out because methotrexate has not demonstrated efficacy for axial disease in psoriatic arthritis, regardless of dose, and biologic therapy is indicated for persistent axial symptoms.', 1),
('d2000000-0000-0000-0000-000000000038', 'B', 'An IL-23 inhibitor is preferred specifically for axial disease over anti-TNF or IL-17 agents', false, 'Ruled out because IL-23 inhibitors have shown less consistent efficacy specifically for axial disease in trials to date, making them a less preferred choice for this domain compared with anti-TNF or IL-17 agents.', 2),
('d2000000-0000-0000-0000-000000000038', 'C', 'Sulfasalazine is the treatment of choice for axial psoriatic arthritis', false, 'Ruled out because sulfasalazine, like methotrexate, is effective for peripheral joint disease but has not shown efficacy for axial disease.', 3),
('d2000000-0000-0000-0000-000000000038', 'D', 'No systemic therapy is indicated until peripheral joint disease also fails methotrexate', false, 'Ruled out because persistent axial symptoms alone, despite adequate conventional therapy, are sufficient indication to escalate to biologic therapy targeting axial disease.', 4),
('d2000000-0000-0000-0000-000000000038', 'E', 'An anti-TNF agent or an IL-17 inhibitor, both of which have demonstrated efficacy for axial psoriatic arthritis/spondyloarthritis, in contrast to conventional synthetic DMARDs which have limited efficacy for axial disease', true, 'Correct. Conventional synthetic DMARDs such as methotrexate have not shown efficacy for axial disease, whereas anti-TNF agents and IL-17 inhibitors both have robust evidence for efficacy in axial spondyloarthritis/axial psoriatic arthritis, making either an appropriate choice here.', 5),
('d2000000-0000-0000-0000-000000000039', 'A', 'Continue the same topical corticosteroid regimen indefinitely without escalation', false, 'Ruled out because an eight-week trial has already shown inadequate response, and continuing unchanged fails to address ongoing symptoms and functional impairment.', 1),
('d2000000-0000-0000-0000-000000000039', 'B', 'Perform surgical excision of all affected oral mucosa', false, 'Ruled out because surgical excision of extensive mucosal disease is not standard management for erosive oral lichen planus; systemic anti-inflammatory treatment is the appropriate escalation.', 2),
('d2000000-0000-0000-0000-000000000039', 'C', 'A systemic immunosuppressive/immunomodulatory agent (e.g. a short course of oral corticosteroids followed by a steroid-sparing agent such as ciclosporin, hydroxychloroquine, or a biologic in refractory cases) with ongoing surveillance for malignant transformation', true, 'Correct. Erosive oral lichen planus refractory to topical corticosteroids warrants escalation to systemic therapy given the significant impact on eating and quality of life, alongside long-term surveillance given the recognised, albeit small, risk of malignant transformation to oral squamous cell carcinoma.', 3),
('d2000000-0000-0000-0000-000000000039', 'D', 'Reassure that erosive oral lichen planus does not require long-term follow-up', false, 'Ruled out because erosive oral lichen planus carries a small but recognised risk of malignant transformation, requiring ongoing surveillance regardless of treatment response.', 4),
('d2000000-0000-0000-0000-000000000039', 'E', 'Switch to a topical antifungal alone, assuming secondary candidiasis is the primary problem', false, 'Ruled out because although secondary candidiasis can complicate oral lichen planus and topical steroid use, it does not represent the primary underlying disease process requiring escalation.', 5),
('d2000000-0000-0000-0000-000000000040', 'A', 'Guttate psoriasis; treat with phototherapy alone as first-line', false, 'Ruled out because guttate psoriasis presents with small droplet-like plaques, typically after streptococcal infection, not the described islands of sparing and follicular papules characteristic of PRP.', 1),
('d2000000-0000-0000-0000-000000000040', 'B', 'Erythrodermic psoriasis; treat identically to plaque psoriasis with standard biologic first-line choice without considering the alternative diagnosis', false, 'Ruled out because the distinctive clinical features here (islands of sparing, follicular papules, orange keratoderma) point away from ordinary psoriasis toward PRP, which can respond differently to standard psoriasis therapies.', 2),
('d2000000-0000-0000-0000-000000000040', 'C', 'Pityriasis rosea; manage with reassurance and no systemic treatment, as the condition is expected to self-resolve within two weeks', false, 'Ruled out because pityriasis rosea presents with a herald patch and christmas-tree distributed oval plaques, not the described PRP-specific features, and does not require this level of specific systemic treatment consideration.', 3),
('d2000000-0000-0000-0000-000000000040', 'D', 'Pityriasis rubra pilaris; systemic retinoids (e.g. acitretin) are an appropriate first-line systemic treatment option, with methotrexate or biologic agents considered for refractory disease', true, 'Correct. The cephalocaudal spread, characteristic islands of sparing, follicular hyperkeratotic papules, and orange-red waxy palmoplantar keratoderma are distinctive for pityriasis rubra pilaris; systemic retinoids are considered first-line systemic therapy, reflecting the underlying disorder of keratinisation.', 4),
('d2000000-0000-0000-0000-000000000040', 'E', 'Seborrhoeic dermatitis; treat with topical antifungal therapy alone as first-line', false, 'Ruled out because seborrhoeic dermatitis produces greasy scaling in sebaceous areas without the islands of sparing, follicular hyperkeratotic papules, or waxy palmoplantar keratoderma seen here, and does not warrant systemic retinoid therapy.', 5),
('d2000000-0000-0000-0000-000000000041', 'A', 'Wide local excision alone with no further staging required, as the lesion is not ulcerated', false, 'Ruled out because absence of ulceration does not remove the indication for sentinel node biopsy once Breslow thickness exceeds the 0.8mm threshold.', 1),
('d2000000-0000-0000-0000-000000000041', 'B', 'Wide local excision (with appropriate margins based on Breslow thickness) and offer sentinel lymph node biopsy for staging', true, 'Correct. Sentinel lymph node biopsy is generally offered for melanomas with Breslow thickness at or above 0.8mm, as this threshold identifies patients with a clinically significant risk of occult nodal metastasis for whom staging affects prognosis and consideration of adjuvant therapy; wide local excision margins are separately guided by Breslow thickness.', 2),
('d2000000-0000-0000-0000-000000000041', 'C', 'Observation only, as thickness below 2mm does not warrant any further intervention', false, 'Ruled out because the relevant threshold for offering sentinel node biopsy is 0.8mm, not 2mm, and observation alone would omit both definitive excision and staging.', 3),
('d2000000-0000-0000-0000-000000000041', 'D', 'Immediate completion lymphadenectomy of the draining nodal basin without prior sentinel node biopsy', false, 'Ruled out because completion lymphadenectomy is not performed without first establishing nodal status via sentinel node biopsy, and is no longer routine even after a positive sentinel node given current evidence.', 4),
('d2000000-0000-0000-0000-000000000041', 'E', 'Adjuvant systemic immunotherapy without any surgical staging', false, 'Ruled out because adjuvant systemic therapy decisions are guided by accurate staging (including nodal status from sentinel node biopsy), which must be established first.', 5),
('d2000000-0000-0000-0000-000000000042', 'A', 'BRAF/MEK inhibitor therapy has no role since immunotherapy is now used exclusively in all BRAF-mutant metastatic melanoma', false, 'Ruled out because targeted BRAF/MEK inhibitor therapy remains an important first-line option, particularly for rapidly progressive symptomatic disease, alongside immunotherapy.', 1),
('d2000000-0000-0000-0000-000000000042', 'B', 'Single-agent chemotherapy (e.g. dacarbazine) remains first-line therapy in BRAF-mutant metastatic melanoma', false, 'Ruled out because chemotherapy has been superseded by targeted therapy and immunotherapy as first-line options in metastatic melanoma, given their superior efficacy.', 2),
('d2000000-0000-0000-0000-000000000042', 'C', 'BRAF inhibitor monotherapy without MEK inhibition is the preferred approach to reduce toxicity', false, 'Ruled out because BRAF inhibitor monotherapy is associated with a higher risk of cutaneous toxicity (including secondary squamous cell carcinomas) due to paradoxical MAPK pathway activation, so combination BRAF/MEK inhibition is preferred over monotherapy.', 3),
('d2000000-0000-0000-0000-000000000042', 'D', 'Combination BRAF and MEK inhibitor therapy (e.g. dabrafenib plus trametinib) is an appropriate first-line option given the rapid onset of action, particularly valuable in this patient with rapidly progressive, symptomatic, high-burden disease, though combination immune checkpoint inhibition is also a reasonable alternative', true, 'Correct. Combination BRAF/MEK inhibitor therapy achieves rapid, high response rates and is particularly useful in patients with rapidly progressive or symptomatic disease needing swift disease control, while combination immune checkpoint inhibition offers more durable long-term responses; choice is individualised based on disease kinetics and patient factors.', 4),
('d2000000-0000-0000-0000-000000000042', 'E', 'Testing for BRAF mutation status is not required before selecting systemic therapy', false, 'Ruled out because BRAF mutation testing is essential in metastatic melanoma as it directly determines eligibility for targeted therapy.', 5),
('d2000000-0000-0000-0000-000000000043', 'A', 'Standard surgical excision with a 4mm margin, as used for low-risk SCC', false, 'Ruled out because a narrow standard margin is appropriate for low-risk SCC, not a high-risk lesion with poor differentiation, perineural invasion and ill-defined margins, where margin control via Mohs surgery is preferred.', 1),
('d2000000-0000-0000-0000-000000000043', 'B', 'Cryotherapy as definitive treatment', false, 'Ruled out because destructive treatments such as cryotherapy lack histological margin control and are inappropriate for high-risk, deeply invasive SCC with perineural invasion.', 2),
('d2000000-0000-0000-0000-000000000043', 'C', 'Mohs micrographic surgery, given the high-risk features (site, size, poor differentiation, perineural invasion, ill-defined margins) that increase the risk of incomplete excision and recurrence with standard excision', true, 'Correct. High-risk features for cutaneous SCC recurrence include size greater than 2cm, poor differentiation, perineural invasion, high-risk anatomical sites, and ill-defined clinical margins; such tumours are best managed with Mohs micrographic surgery to maximise complete tumour clearance while sparing tissue in this cosmetically and functionally sensitive area.', 3),
('d2000000-0000-0000-0000-000000000043', 'D', 'Topical 5-fluorouracil as monotherapy', false, $x$Ruled out because topical therapy is appropriate for superficial, low-risk lesions such as actinic keratosis or Bowen's disease, not invasive high-risk SCC.$x$, 4),
('d2000000-0000-0000-0000-000000000043', 'E', 'Observation with interval clinical review only, given his age', false, 'Ruled out because high-risk SCC with perineural invasion requires active treatment regardless of age, given the risk of local recurrence and further spread if untreated.', 5),
('d2000000-0000-0000-0000-000000000044', 'A', 'A hedgehog pathway inhibitor (e.g. vismodegib or sonidegib)', true, 'Correct. Hedgehog pathway inhibitors are targeted oral therapies licensed for locally advanced or metastatic basal cell carcinoma not amenable to surgery or radiotherapy, exploiting the near-universal dysregulation of hedgehog signalling in BCC.', 1),
('d2000000-0000-0000-0000-000000000044', 'B', 'Systemic cytotoxic chemotherapy as first-line treatment', false, 'Ruled out because targeted hedgehog pathway inhibitor therapy, not conventional cytotoxic chemotherapy, is the standard systemic option for locally advanced BCC not amenable to surgery or radiotherapy.', 2),
('d2000000-0000-0000-0000-000000000044', 'C', 'Immune checkpoint inhibitor monotherapy as first-line treatment for locally advanced disease', false, 'Ruled out because anti-PD-1 immunotherapy is reserved for patients who have progressed on or are intolerant of hedgehog pathway inhibitor therapy, not as routine first-line treatment.', 3),
('d2000000-0000-0000-0000-000000000044', 'D', 'Topical imiquimod as definitive treatment for this extent of disease', false, 'Ruled out because topical imiquimod is appropriate for superficial, low-risk BCC, not a large, locally invasive, periosteum-involving tumour.', 4),
('d2000000-0000-0000-0000-000000000044', 'E', 'Watchful waiting with no active treatment given his age and comorbidities', false, 'Ruled out because effective, well-tolerated oral targeted therapy exists for this scenario and should be offered rather than defaulting to no treatment.', 5),
('d2000000-0000-0000-0000-000000000045', 'A', 'Wide local excision of the primary lesion alone is sufficient, with no need for nodal assessment or treatment given a single involved node', false, 'Ruled out because even a single involved node carries significant risk of further micrometastatic spread in this highly aggressive tumour, warranting active nodal basin treatment, not excision of the primary alone.', 1),
('d2000000-0000-0000-0000-000000000045', 'B', 'Topical imiquimod as monotherapy is appropriate given the rapid growth', false, 'Ruled out because topical therapy is entirely inadequate for an aggressive neuroendocrine carcinoma with confirmed nodal spread; surgical/radiotherapeutic management is required.', 2),
('d2000000-0000-0000-0000-000000000045', 'C', 'Immune checkpoint inhibitor therapy should be used as sole first-line treatment instead of surgery for regionally confined disease', false, 'Ruled out because for regionally confined (primary plus single node) disease, surgery (with or without radiotherapy) remains the standard approach; checkpoint inhibitors are the mainstay for advanced/metastatic disease, and immunosuppressed transplant patients also carry competing graft-rejection risk with checkpoint inhibition.', 3),
('d2000000-0000-0000-0000-000000000045', 'D', 'Observation alone is appropriate given his overall comorbidity burden from transplantation', false, 'Ruled out because Merkel cell carcinoma is highly aggressive with a significant propensity for further spread, so active treatment of both the primary and nodal disease is warranted despite comorbidities, with careful multidisciplinary planning.', 4),
('d2000000-0000-0000-0000-000000000045', 'E', 'Wide local excision of the primary lesion with lymph node dissection (or radiotherapy) to the involved nodal basin, given the aggressive nature and high metastatic potential of Merkel cell carcinoma', true, $x$Correct. Management of regionally confined Merkel cell carcinoma typically combines surgical excision of the primary with treatment of the nodal basin, reflecting the high risk of micrometastatic spread even with a single clinically involved node, given the tumour's aggressive behaviour, particularly in immunosuppressed patients.$x$, 5),
('d2000000-0000-0000-0000-000000000046', 'A', 'Comprehensive age- and sex-appropriate malignancy screening (including relevant imaging and cancer-specific screening), given the strong association between anti-TIF1-gamma positive dermatomyositis and underlying malignancy', true, 'Correct. Anti-TIF1-gamma positive dermatomyositis carries one of the strongest associations with underlying malignancy among the myositis-specific antibodies, particularly in adults over 40, warranting thorough, often repeated, malignancy screening around the time of diagnosis.', 1),
('d2000000-0000-0000-0000-000000000046', 'B', 'No additional malignancy screening is required beyond routine age-appropriate national screening programmes', false, 'Ruled out because anti-TIF1-gamma positivity substantially raises malignancy risk above baseline, warranting more comprehensive, targeted screening beyond routine population programmes.', 2),
('d2000000-0000-0000-0000-000000000046', 'C', 'Malignancy association is only relevant in dermatomyositis without cutaneous involvement', false, 'Ruled out because malignancy association is actually strongest in classic dermatomyositis with cutaneous features, particularly with certain myositis-specific antibodies such as anti-TIF1-gamma.', 3),
('d2000000-0000-0000-0000-000000000046', 'D', 'Start high-dose corticosteroids alone with no further investigation, as antibody status does not affect management', false, 'Ruled out because antibody status (anti-TIF1-gamma) directly informs malignancy risk and should guide the intensity of screening alongside treatment of the myositis/skin disease.', 4),
('d2000000-0000-0000-0000-000000000046', 'E', 'Malignancy screening should be deferred for at least 2 years as risk is only delayed-onset', false, 'Ruled out because malignancy risk in dermatomyositis is highest in the first 1-2 years around diagnosis, so screening should be prompt, not deferred.', 5),
('d2000000-0000-0000-0000-000000000047', 'A', 'Aggressive glycaemic optimisation alone is expected to resolve the skin lesions', false, 'Ruled out because, as demonstrated here, optimising glycaemic control does not reliably improve established necrobiosis lipoidica lesions, so this cannot be relied upon as sole management.', 1),
('d2000000-0000-0000-0000-000000000047', 'B', 'Surgical excision of all affected skin is the treatment of choice', false, 'Ruled out because surgical excision is not standard first-line treatment for necrobiosis lipoidica and carries risk of poor wound healing in atrophic, fragile skin.', 2),
('d2000000-0000-0000-0000-000000000047', 'C', 'Topical antifungal therapy, as the presentation reflects a fungal infection', false, 'Ruled out because the clinical description (yellow-brown atrophic telangiectatic plaques with violaceous border in a diabetic patient) is characteristic of necrobiosis lipoidica, not a fungal infection.', 3),
('d2000000-0000-0000-0000-000000000047', 'D', 'Potent topical or intralesional corticosteroids to active inflammatory borders, alongside protection from trauma; note that improving glycaemic control alone does not reliably improve established lesions', true, $x$Correct. Necrobiosis lipoidica is strongly associated with diabetes but its course does not reliably correlate with glycaemic control; active, inflamed lesions are treated with potent topical or intralesional corticosteroids at the advancing border, used cautiously given the lesions' inherent tendency towards atrophy, alongside trauma protection.$x$, 4),
('d2000000-0000-0000-0000-000000000047', 'E', 'Reassurance only, as necrobiosis lipoidica has no available treatment options and always resolves spontaneously', false, 'Ruled out because effective treatment options exist (topical/intralesional corticosteroids, phototherapy, or systemic agents for refractory disease) and spontaneous resolution is not reliable.', 5),
('d2000000-0000-0000-0000-000000000048', 'A', 'Urgent surgical debridement is the priority to remove necrotic tissue and promote healing', false, 'Ruled out because surgical debridement risks worsening pyoderma gangrenosum via pathergy and should be avoided or minimised; systemic immunosuppression is the priority instead.', 1),
('d2000000-0000-0000-0000-000000000048', 'B', 'Avoid surgical debridement or aggressive wound surgery, as pyoderma gangrenosum exhibits pathergy; management should focus on systemic immunosuppression (e.g. corticosteroids, ciclosporin, or anti-TNF agents given the coexisting IBD) alongside gentle wound care', true, 'Correct. Pyoderma gangrenosum characteristically demonstrates pathergy, whereby trauma including surgical debridement can trigger new lesions or worsen existing ones, so surgery should be avoided or minimised; systemic immunosuppression, particularly anti-TNF therapy given the coexisting IBD, is the mainstay of treatment.', 2),
('d2000000-0000-0000-0000-000000000048', 'C', 'Treat with prolonged broad-spectrum antibiotics alone, as the underlying process is a bacterial skin and soft tissue infection', false, 'Ruled out because wound swabs show no significant bacterial growth and biopsy confirms pyoderma gangrenosum, a neutrophilic inflammatory (not primarily infective) process requiring immunosuppression.', 3),
('d2000000-0000-0000-0000-000000000048', 'D', 'Skin grafting should be performed as first-line treatment before any systemic therapy', false, 'Ruled out because grafting onto actively inflamed pyoderma gangrenosum tissue risks pathergy-driven graft failure and worsening; systemic disease control should precede any surgical intervention.', 4),
('d2000000-0000-0000-0000-000000000048', 'E', 'Topical antiseptic dressings alone are sufficient, with no role for systemic treatment', false, 'Ruled out because topical dressings alone do not address the underlying neutrophilic inflammatory process; systemic immunosuppression is required for disease control.', 5),
('d2000000-0000-0000-0000-000000000049', 'A', 'Continue warfarin unchanged, as it is unrelated to the underlying pathology', false, 'Ruled out because warfarin is a recognised risk factor for calciphylaxis via inhibition of vitamin K-dependent matrix Gla protein, and should be discontinued with an alternative anticoagulation strategy considered.', 1),
('d2000000-0000-0000-0000-000000000049', 'B', 'Manage with surgical debridement as the primary and sufficient treatment without addressing systemic factors', false, 'Ruled out because surgical debridement alone, without addressing calcium-phosphate balance, warfarin use, and systemic therapy, is inadequate management for calciphylaxis.', 2),
('d2000000-0000-0000-0000-000000000049', 'C', 'Stop warfarin (switching to an alternative anticoagulant if still required) and start IV sodium thiosulfate, alongside optimising calcium-phosphate balance and aggressive wound care and pain management', true, 'Correct. Warfarin inhibits matrix Gla protein, a vascular calcification inhibitor, and is a recognised risk factor for calciphylaxis, so it should be stopped; sodium thiosulfate, correction of calcium-phosphate balance, and aggressive wound care and analgesia form the multimodal management approach.', 3),
('d2000000-0000-0000-0000-000000000049', 'D', 'Increase active vitamin D analogue dose to improve bone health, irrespective of calcium-phosphate status', false, 'Ruled out because increasing active vitamin D without regard to calcium-phosphate status could worsen vascular calcification, the core pathology in calciphylaxis.', 4),
('d2000000-0000-0000-0000-000000000049', 'E', 'Treat as cellulitis with a prolonged course of oral antibiotics as the primary intervention', false, 'Ruled out because although secondary infection can complicate calciphylaxis ulcers, the primary pathology is vascular calcification and thrombosis, requiring disease-specific treatment, not antibiotics alone.', 5),
('d2000000-0000-0000-0000-000000000050', 'A', 'Discoid lupus erythematosus; treat with topical corticosteroids alone with no systemic work-up required', false, 'Ruled out because the biopsy finding of non-caseating granulomas together with bilateral hilar lymphadenopathy and pulmonary infiltrates supports sarcoidosis rather than discoid lupus erythematosus, and systemic work-up and treatment are required given the pulmonary involvement.', 1),
('d2000000-0000-0000-0000-000000000050', 'B', 'Rosacea; manage with oral tetracyclines as first-line treatment', false, 'Ruled out because rosacea does not produce non-caseating granulomas on biopsy or bilateral hilar lymphadenopathy with pulmonary infiltrates; this presentation is consistent with sarcoidosis, not rosacea.', 2),
('d2000000-0000-0000-0000-000000000050', 'C', 'Granulomatosis with polyangiitis; start immediate high-dose cyclophosphamide without further confirmatory testing', false, 'Ruled out because granulomatosis with polyangiitis typically shows necrotising granulomatous inflammation with vasculitis and ANCA positivity, differing from the non-caseating granulomas and bilateral hilar lymphadenopathy pattern seen here, which is characteristic of sarcoidosis.', 3),
('d2000000-0000-0000-0000-000000000050', 'D', 'Cutaneous tuberculosis; start empirical anti-tuberculous quadruple therapy without further investigation', false, 'Ruled out because although TB can cause granulomatous disease, non-caseating (rather than caseating) granulomas together with bilateral hilar lymphadenopathy and the classic lupus pernio distribution favour sarcoidosis, and empirical anti-TB therapy without confirmatory testing would be inappropriate.', 4),
('d2000000-0000-0000-0000-000000000050', 'E', 'Lupus pernio (a chronic, disfiguring cutaneous manifestation of sarcoidosis) with associated pulmonary involvement; given the disfigurement and pulmonary involvement, systemic treatment with oral corticosteroids (with steroid-sparing agents such as methotrexate for long-term/relapsing disease) is appropriate', true, 'Correct. Lupus pernio is a distinctive, chronic form of cutaneous sarcoidosis strongly associated with chronic pulmonary sarcoidosis; non-caseating granulomas on biopsy with bilateral hilar lymphadenopathy and pulmonary infiltrates support sarcoidosis, and given cosmetic disfigurement, risk of nasal/airway compromise and pulmonary involvement, systemic corticosteroid therapy (with steroid-sparing agents for chronic disease) is warranted rather than topical treatment alone.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d2000000-0000-0000-0000-000000000001', 'In elderly patients, especially those with comorbidities, superpotent topical corticosteroids applied to the whole body are as effective as oral corticosteroids in controlling bullous pemphigoid and are associated with significantly lower mortality and treatment-related morbidity.', 1),
('d2000000-0000-0000-0000-000000000001', 'Systemic corticosteroids in frail elderly patients carry higher risk of infection, fractures and death, favouring topical-first strategies where feasible and where adequate application can be ensured (e.g. with carer support).', 2),
('d2000000-0000-0000-0000-000000000001', 'DIF showing linear IgG/C3 along the basement membrane zone (versus the intraepidermal pattern seen in pemphigus) confirms subepidermal blistering typical of bullous pemphigoid.', 3),
('d2000000-0000-0000-0000-000000000002', 'Rituximab (anti-CD20) combined with a short course of corticosteroids is recommended as first-line therapy for moderate-to-severe pemphigus vulgaris and is the treatment of choice for relapse during or after corticosteroid taper.', 1),
('d2000000-0000-0000-0000-000000000002', 'Rising anti-desmoglein 3 antibody titres correlate with disease activity and relapse risk and can help guide treatment decisions alongside clinical findings.', 2),
('d2000000-0000-0000-0000-000000000002', 'Escalating corticosteroids alone perpetuates cumulative steroid toxicity without targeting the underlying autoantibody-producing B-cell population.', 3),
('d2000000-0000-0000-0000-000000000003', 'Dapsone causes dose-dependent haemolysis in all patients but this is markedly more severe in G6PD deficiency, so G6PD status must be checked before starting therapy.', 1),
('d2000000-0000-0000-0000-000000000003', 'Dapsone provides rapid symptomatic relief in DH within days, but does not treat the underlying gluten sensitivity; a strict lifelong gluten-free diet remains the definitive treatment and may allow dapsone to be weaned over time.', 2),
('d2000000-0000-0000-0000-000000000003', 'Regular monitoring of full blood count (for haemolysis/agranulocytosis) and methaemoglobin level is required throughout dapsone therapy.', 3),
('d2000000-0000-0000-0000-000000000004', 'Vancomycin is the most commonly implicated drug in drug-induced linear IgA bullous dermatosis; the classic string-of-pearls annular blistering pattern at the margin of urticated plaques is a recognised feature.', 1),
('d2000000-0000-0000-0000-000000000004', 'Drug-induced LABD typically resolves rapidly after withdrawal of the causative agent, distinguishing management from idiopathic linear IgA disease, which often requires dapsone or sulfonamides.', 2),
('d2000000-0000-0000-0000-000000000004', 'Rechallenge with the causative drug should be avoided given the risk of recurrence.', 3),
('d2000000-0000-0000-0000-000000000005', 'Salt-split skin immunofluorescence localises the target antigen: epidermal (roof) binding indicates bullous pemphigoid (against BP180/BP230 in the hemidesmosome), while dermal (floor) binding indicates epidermolysis bullosa acquisita (against type VII collagen in the anchoring fibrils) or anti-p200 pemphigoid.', 1),
('d2000000-0000-0000-0000-000000000005', 'EBA is associated with inflammatory bowel disease and often follows a mechanobullous, scarring course with milia, distinguishing it clinically from bullous pemphigoid.', 2),
('d2000000-0000-0000-0000-000000000005', 'EBA is generally more resistant to standard immunosuppressive regimens than bullous pemphigoid, often requiring combination therapy.', 3),
('d2000000-0000-0000-0000-000000000006', 'Ocular (and laryngeal/oesophageal) involvement in mucous membrane pemphigoid signifies high-risk disease due to the potential for blindness or airway compromise from scarring, and mandates prompt escalation to potent systemic immunosuppression rather than continued topical or dapsone therapy.', 1),
('d2000000-0000-0000-0000-000000000006', 'Disease activity should be closely monitored jointly with ophthalmology, as scarring is irreversible once established, unlike the inflammatory phase which can still be modified by treatment.', 2),
('d2000000-0000-0000-0000-000000000006', 'Progression despite dapsone indicates treatment failure requiring escalation in therapeutic intensity, not simply prolonging the same regimen.', 3),
('d2000000-0000-0000-0000-000000000007', 'Immediate withdrawal of the culprit drug is the single most important intervention in SJS/TEN and improves survival; the causative agent should never be continued or rechallenged.', 1),
('d2000000-0000-0000-0000-000000000007', 'SCORTEN uses age >40, malignancy, heart rate >120, initial epidermal detachment >10%, serum urea >10mmol/L, glucose >14mmol/L, and bicarbonate <20mmol/L to estimate mortality risk, and should be calculated early to guide the intensity of supportive care and unit-level transfer.', 2),
('d2000000-0000-0000-0000-000000000007', 'Specialist supportive care (burns-unit-level wound care, fluid and thermoregulation, early ophthalmology, and nutritional support) is the evidence-based mainstay of management; adjuncts such as IVIG remain of unproven, inconsistent benefit.', 3),
('d2000000-0000-0000-0000-000000000008', 'DRESS has a delayed onset (typically 2-8 weeks after starting the culprit drug), distinguishing it from more immediate hypersensitivity reactions, and allopurinol is one of the most frequently implicated drugs.', 1),
('d2000000-0000-0000-0000-000000000008', 'Systemic corticosteroids are the mainstay of treatment for significant organ involvement in DRESS, though the disease can relapse or flare during steroid tapering, requiring slow tapering and monitoring.', 2),
('d2000000-0000-0000-0000-000000000008', 'HHV-6 (and other herpesvirus) reactivation is a recognised feature of DRESS and may contribute to its severity and prolonged/relapsing course, but antiviral therapy is not routine first-line treatment.', 3),
('d2000000-0000-0000-0000-000000000009', 'AGEP has a very short latency after drug exposure (usually 1-2 days, particularly with antibiotics such as aminopenicillins), in contrast to the more chronic, often non-drug-related pattern of generalised pustular psoriasis.', 1),
('d2000000-0000-0000-0000-000000000009', 'Histology distinguishes the two: AGEP shows spongiform subcorneal pustules with papillary dermal oedema but lacks the epidermal changes (acanthosis, elongated rete ridges) typically seen in psoriasis.', 2),
('d2000000-0000-0000-0000-000000000009', 'Management of AGEP is drug withdrawal and supportive care; it is usually self-limiting and does not require the systemic agents used for generalised pustular psoriasis.', 3),
('d2000000-0000-0000-0000-000000000010', $x$Erythroderma causes major disruption to the skin's barrier and thermoregulatory functions: increased cutaneous blood flow and transepidermal water/heat loss can precipitate hypothermia, dehydration, hypoalbuminaemia and high-output cardiac failure, particularly in elderly patients with reduced cardiac reserve.$x$, 1),
('d2000000-0000-0000-0000-000000000010', 'Abrupt withdrawal of systemic agents such as methotrexate or systemic corticosteroids in psoriasis is a recognised precipitant of erythroderma/psoriatic flare and should be avoided.', 2),
('d2000000-0000-0000-0000-000000000010', 'Management is largely supportive (temperature regulation, fluid balance, monitoring for secondary infection) alongside identifying and treating the underlying dermatosis or trigger.', 3),
('d2000000-0000-0000-0000-000000000011', 'Fixed drug eruption characteristically recurs at the same anatomical site with each rechallenge and can become more severe (including bullous change) with repeated exposure, prompting strict avoidance rather than dose reduction.', 1),
('d2000000-0000-0000-0000-000000000011', 'Co-trimoxazole (via its sulfonamide component) is a classic cause of fixed drug eruption; trimethoprim alone can still occasionally cross-react and is not automatically safe.', 2),
('d2000000-0000-0000-0000-000000000011', 'Clear documentation and allergy alerting is essential given the risk of increasingly severe reactions, including generalised bullous fixed drug eruption, on further re-exposure.', 3),
('d2000000-0000-0000-0000-000000000012', 'SSSS results from circulating staphylococcal exfoliative toxins cleaving desmoglein 1 in the superficial epidermis (subcorneal split), causing widespread superficial peeling that spares mucosa, in contrast to TEN, which shows full-thickness epidermal necrosis and prominent mucosal involvement.', 1),
('d2000000-0000-0000-0000-000000000012', 'SSSS is treated with antistaphylococcal antibiotics and supportive skin/wound care; systemic corticosteroids or other immunosuppression have no role and may worsen outcomes by impairing infection clearance.', 2),
('d2000000-0000-0000-0000-000000000012', 'SSSS occurs more commonly in young children and in adults with renal impairment or immunosuppression (reduced toxin clearance), an important risk factor to recognise in adults presenting with this pattern.', 3),
('d2000000-0000-0000-0000-000000000013', 'Eczema herpeticum is a dermatological emergency caused by widespread HSV infection on a background of disrupted skin barrier; treatment with systemic aciclovir should not be delayed pending swab confirmation given the risk of dissemination, herpetic keratitis, and death.', 1),
('d2000000-0000-0000-0000-000000000013', 'Increasing topical corticosteroids in this setting would worsen the infection and is contraindicated until the herpetic infection is controlled.', 2),
('d2000000-0000-0000-0000-000000000013', 'Periocular involvement warrants urgent ophthalmology review given the risk of herpetic keratitis and sight-threatening complications.', 3),
('d2000000-0000-0000-0000-000000000014', 'International urticaria guidelines recommend a stepwise approach: standard-dose non-sedating H1-antihistamine, then up-dosing to four times the licensed dose, and if still uncontrolled, addition of omalizumab, with ciclosporin reserved for omalizumab-refractory cases.', 1),
('d2000000-0000-0000-0000-000000000014', 'Long-term oral corticosteroids are not recommended for maintenance therapy in chronic urticaria due to cumulative toxicity; short courses may be used only for severe exacerbations.', 2),
('d2000000-0000-0000-0000-000000000014', 'Chronic spontaneous urticaria is not typically driven by identifiable external allergens, so allergy/skin prick testing has limited value in guiding treatment and is not part of the standard escalation pathway.', 3),
('d2000000-0000-0000-0000-000000000015', 'Patch test reading requires distinguishing true allergic (crescendo reaction, may persist/increase from 48 to 96 hours, may show vesiculation) from irritant reactions (typically fading by 96 hours, sharply demarcated, without vesicles) — irritant reactions are not evidence of allergic contact sensitisation.', 1),
('d2000000-0000-0000-0000-000000000015', $x$Clinical relevance must be established by correlating positive patch test results with the patient's exposure history and dermatitis distribution — an occupational hairdresser with hand dermatitis and strong PPD positivity has an occupationally relevant allergy.$x$, 2),
('d2000000-0000-0000-0000-000000000015', 'PPD is a major allergen in hair dye and can cross-react with related para-amino compounds, which should be discussed as part of allergen avoidance advice.', 3),
('d2000000-0000-0000-0000-000000000016', 'Oral JAK inhibitors used in moderate-to-severe atopic dermatitis carry a boxed warning for increased risk of major adverse cardiovascular events, venous thromboembolism, malignancy, and serious infection, requiring careful patient selection and baseline risk assessment.', 1),
('d2000000-0000-0000-0000-000000000016', 'Baseline screening should include infection screen (TB, viral hepatitis), lipid profile, full blood count, and assessment of cardiovascular and thromboembolic risk factors before initiation.', 2),
('d2000000-0000-0000-0000-000000000016', 'Renal function should be reassessed as a new baseline rather than assumed, particularly following previous nephrotoxic therapy such as ciclosporin.', 3),
('d2000000-0000-0000-0000-000000000017', 'Hereditary angioedema (C1 inhibitor deficiency) is a bradykinin-mediated, not mast-cell/histamine-mediated, process, so it does not respond to antihistamines, corticosteroids, or adrenaline — first-line acute treatment is C1 esterase inhibitor concentrate or icatibant.', 1),
('d2000000-0000-0000-0000-000000000017', 'The absence of urticarial wheals, family history, and lack of response to standard anti-allergic treatment are important clues distinguishing HAE from mast-cell-mediated angioedema/urticaria.', 2),
('d2000000-0000-0000-0000-000000000017', 'Low C4 (a useful screening test) with reduced C1 inhibitor level and/or function confirms the diagnosis; long-term prophylaxis may be considered for patients with frequent attacks.', 3),
('d2000000-0000-0000-0000-000000000018', 'Urticarial vasculitis is distinguished clinically from ordinary urticaria by individual lesions lasting more than 24 hours, residual bruising/pigmentation, burning rather than itch, and possible systemic features (arthralgia, renal involvement); biopsy shows leukocytoclastic vasculitis.', 1),
('d2000000-0000-0000-0000-000000000018', 'Hypocomplementaemic urticarial vasculitis (low C3/C4) is more likely to be associated with systemic disease (especially SLE) and systemic organ involvement (renal, pulmonary), warranting a broader autoimmune work-up.', 2),
('d2000000-0000-0000-0000-000000000018', 'Management differs from ordinary chronic urticaria: antihistamines alone are usually inadequate, and systemic anti-inflammatory/immunosuppressive treatment is often required, guided by severity and any underlying systemic disease.', 3),
('d2000000-0000-0000-0000-000000000019', 'Isotretinoin is a potent teratogen; the Pregnancy Prevention Programme mandates monthly pregnancy testing throughout treatment and for a period after stopping, with continuous effective contraception (ideally two methods) for the entire treatment duration.', 1),
('d2000000-0000-0000-0000-000000000019', 'Baseline and periodic monitoring of liver function tests and fasting lipid profile is recommended, as isotretinoin can cause transaminitis and hypertriglyceridaemia/hypercholesterolaemia.', 2),
('d2000000-0000-0000-0000-000000000019', 'Current guidance recommends monitoring mood and mental health throughout treatment, with prompt action if symptoms emerge, even though a definitive causal link with depression/suicidality remains debated.', 3),
('d2000000-0000-0000-0000-000000000020', 'Adalimumab is licensed and recommended as the next step for moderate-to-severe hidradenitis suppurativa that has failed conventional systemic antibiotic therapy, targeting the underlying TNF-alpha-driven inflammatory process.', 1),
('d2000000-0000-0000-0000-000000000020', 'Isotretinoin has limited and inconsistent efficacy in HS (unlike in acne) and is not considered an appropriate next-line therapy for treatment-resistant disease.', 2),
('d2000000-0000-0000-0000-000000000020', 'Surgery (deroofing or wide excision) has an important role in HS, particularly for localised, fibrotic or sinus tract disease, but is typically considered alongside or after medical optimisation rather than replacing it when active inflammatory disease is escalating.', 3),
('d2000000-0000-0000-0000-000000000021', 'Acne fulminans is an acute, severe, ulcerative variant of acne with systemic inflammatory features; starting isotretinoin without prior corticosteroid control can precipitate a severe flare, so oral corticosteroids should be commenced first (often for several weeks).', 1),
('d2000000-0000-0000-0000-000000000021', 'Isotretinoin is typically introduced at a low dose and slowly up-titrated only once the acute flare is controlled with corticosteroids, with corticosteroids continued in overlap and then tapered.', 2),
('d2000000-0000-0000-0000-000000000021', 'Systemic symptoms (fever, arthralgia, raised inflammatory markers) reflect an immune-mediated inflammatory reaction rather than primary bacterial infection, so escalating antibiotics alone is not the priority.', 3),
('d2000000-0000-0000-0000-000000000022', 'Phymatous rosacea reflects sebaceous gland hyperplasia and fibrosis and responds poorly to antibiotics (which target the inflammatory papulopustular component); low-dose isotretinoin can reduce sebaceous gland activity but established architectural change is often best addressed with surgical or laser recontouring.', 1),
('d2000000-0000-0000-0000-000000000022', 'Long-term topical or systemic corticosteroids can worsen rosacea (and may cause steroid-induced rosacea/perioral dermatitis) and should be avoided.', 2),
('d2000000-0000-0000-0000-000000000022', 'Recognising the different rosacea subtypes (erythematotelangiectatic, papulopustular, phymatous, ocular) is important as treatment approaches differ substantially between them.', 3),
('d2000000-0000-0000-0000-000000000023', 'Perioral dermatitis is frequently caused or exacerbated by topical corticosteroid use on the face; abrupt cessation causes rebound worsening, so a gradual weaning strategy alongside oral tetracyclines is the standard approach.', 1),
('d2000000-0000-0000-0000-000000000023', 'Escalating corticosteroid potency perpetuates the underlying problem and delays resolution.', 2),
('d2000000-0000-0000-0000-000000000023', 'The characteristic sparing of a narrow zone around the vermilion border helps distinguish perioral dermatitis from other facial dermatoses such as acne or contact dermatitis.', 3),
('d2000000-0000-0000-0000-000000000024', 'Isotretinoin and tetracyclines (including doxycycline) are both contraindicated in pregnancy — isotretinoin is a potent teratogen, and tetracyclines cause fetal teeth discolouration and can affect bone growth — so alternative agents must be selected.', 1),
('d2000000-0000-0000-0000-000000000024', 'Oral corticosteroids can be used cautiously for short-term control of severe inflammatory flares in pregnancy when the benefit outweighs the risk, under specialist guidance.', 2),
('d2000000-0000-0000-0000-000000000024', 'Erythromycin and azelaic acid are considered relatively safe alternatives for acne/rosacea-type disease in pregnancy when systemic or topical therapy is required.', 3),
('d2000000-0000-0000-0000-000000000025', 'Oral JAK inhibitors have demonstrated efficacy in regrowing hair in moderate-to-severe alopecia areata refractory to topical/intralesional treatment and contact immunotherapy, and are now a recognised treatment option in this setting.', 1),
('d2000000-0000-0000-0000-000000000025', 'As with other indications, JAK inhibitor use requires baseline screening for infection (including TB), assessment of cardiovascular/thromboembolic risk, and ongoing monitoring given class-wide safety signals.', 2),
('d2000000-0000-0000-0000-000000000025', 'Hair transplantation is not appropriate in active alopecia areata, as it is an autoimmune process that can affect transplanted follicles, and has no role until disease activity is stable/quiescent.', 3),
('d2000000-0000-0000-0000-000000000026', 'Finasteride (a 5-alpha reductase inhibitor) reduces conversion of testosterone to dihydrotestosterone; recognised side effects include sexual dysfunction, which usually resolves on stopping but has (rarely) been reported to persist, and this should be part of informed consent discussion.', 1),
('d2000000-0000-0000-0000-000000000026', 'Finasteride tablets should not be handled by women who are or may become pregnant due to teratogenic risk to a male fetus, an important counselling point given potential household exposure.', 2),
('d2000000-0000-0000-0000-000000000026', 'Finasteride is not associated with a well-established hepatotoxicity monitoring requirement in the way isotretinoin is, and routine LFT monitoring is not a standard requirement.', 3),
('d2000000-0000-0000-0000-000000000027', 'Lichen planopilaris is a primary scarring (cicatricial) alopecia in which active inflammation destroys the follicular stem cell niche irreversibly, making early disease suppression critical, unlike non-scarring alopecias where lost follicles can regrow.', 1),
('d2000000-0000-0000-0000-000000000027', 'Treatment aims to halt disease activity (reduce erythema, scaling, symptoms and further hair loss) rather than regrow hair in already-scarred areas; options range from potent topical/intralesional corticosteroids to hydroxychloroquine or other systemic immunosuppressants for progressive disease.', 2),
('d2000000-0000-0000-0000-000000000027', 'Hair transplantation may be considered only once disease activity has been stable/quiescent for a prolonged period, as transplanted follicles can otherwise be affected by ongoing inflammation.', 3),
('d2000000-0000-0000-0000-000000000028', 'Nail psoriasis and onychomycosis can closely mimic one another and frequently coexist, as psoriatic nail dystrophy predisposes to fungal superinfection; mycological confirmation or exclusion should be sought before committing to systemic immunosuppressive/biologic therapy targeted at psoriasis.', 1),
('d2000000-0000-0000-0000-000000000028', 'Missing a concurrent fungal infection before starting immunosuppressive biologic therapy risks worsening the fungal infection.', 2),
('d2000000-0000-0000-0000-000000000028', 'Oil-drop/salmon patch discoloration, pitting and onycholysis are classic for psoriatic nail disease, but clinical overlap with onychomycosis means investigation is still warranted, particularly before major treatment escalation.', 3),
('d2000000-0000-0000-0000-000000000029', 'The stepwise management ladder for primary focal hyperhidrosis progresses from topical aluminium salts, to botulinum toxin A injections if topical treatment fails, then to oral anticholinergics or further procedural options, with sympathectomy reserved as a later/last resort given the risk of compensatory hyperhidrosis.', 1),
('d2000000-0000-0000-0000-000000000029', 'Iontophoresis is most useful for palmoplantar hyperhidrosis rather than axillary disease, where access/technique makes it less practical.', 2),
('d2000000-0000-0000-0000-000000000029', 'Endoscopic thoracic sympathectomy carries a significant risk of compensatory sweating elsewhere on the body and is generally reserved for severe palmar hyperhidrosis refractory to other measures.', 3),
('d2000000-0000-0000-0000-000000000030', 'Anagen effluvium (classically from cytotoxic chemotherapy or radiation) interrupts hair matrix mitosis directly during the active growth phase, causing rapid hair loss within days to a couple of weeks of the insult.', 1),
('d2000000-0000-0000-0000-000000000030', 'Telogen effluvium follows a physiological trigger (illness, major stress, surgery, childbirth, severe dietary restriction) that prematurely shifts follicles from anagen into telogen; because telogen lasts around three months before the hair is shed, hair loss characteristically appears roughly 2-3 months after the triggering event.', 2),
('d2000000-0000-0000-0000-000000000030', 'Understanding this latency is clinically useful for identifying the causative trigger when taking a history in a patient presenting with diffuse hair shedding.', 3),
('d2000000-0000-0000-0000-000000000031', $x$Hutchinson's sign (vesicles on the tip, side or root of the nose, reflecting nasociliary nerve involvement) strongly predicts ocular involvement in herpes zoster ophthalmicus and should prompt urgent ophthalmology referral regardless of current visual symptoms.$x$, 1),
('d2000000-0000-0000-0000-000000000031', 'Early systemic antiviral therapy reduces the risk and severity of ocular complications and postherpetic neuralgia; topical antivirals are inadequate for zoster.', 2),
('d2000000-0000-0000-0000-000000000031', 'HZO can cause serious ocular complications including keratitis, uveitis, and in severe cases vision loss, making prompt combined dermatological/ophthalmological management essential.', 3),
('d2000000-0000-0000-0000-000000000032', 'Necrotising fasciitis is a surgical emergency; clinical suspicion (pain out of proportion, rapidly progressive erythema, bullae, systemic toxicity, gas on imaging) should prompt immediate surgical debridement without waiting for definitive imaging, as delay significantly increases mortality.', 1),
('d2000000-0000-0000-0000-000000000032', 'Antibiotics and resuscitation are important adjuncts but are not a substitute for source control via surgical debridement, which is the single most important determinant of survival.', 2),
('d2000000-0000-0000-0000-000000000032', 'Diabetes is a recognised risk factor for necrotising soft tissue infection and can also mask the severity of pain, so a high index of suspicion is needed even when pain appears modest.', 3),
('d2000000-0000-0000-0000-000000000033', 'Crusted (Norwegian) scabies occurs in immunosuppressed or debilitated patients due to an impaired immune response allowing massive mite proliferation; it is highly contagious (unlike ordinary scabies) due to the enormous mite burden, requiring strict isolation and barrier nursing precautions.', 1),
('d2000000-0000-0000-0000-000000000033', 'Treatment requires combination and often repeated dosing (oral ivermectin on multiple days, combined with topical scabicide applied to the whole body including under nails/scalp) because the thick crust can shield mites from single-dose or topical-only treatment.', 2),
('d2000000-0000-0000-0000-000000000033', 'Minimal itching, despite extensive involvement, is characteristic of crusted scabies and reflects blunted immune/inflammatory response rather than lower mite burden, which is in fact very high.', 3),
('d2000000-0000-0000-0000-000000000034', 'Tinea incognito results from application of topical corticosteroids to an unrecognised dermatophyte infection, which suppresses the typical inflammatory features and well-demarcated annular border, allowing the fungal infection to spread more extensively while symptoms are temporarily masked.', 1),
('d2000000-0000-0000-0000-000000000034', 'Mycological confirmation (skin scrapings for microscopy/culture) should be sought whenever a worsening or spreading eczema fails to fit the expected pattern, especially after topical corticosteroid use.', 2),
('d2000000-0000-0000-0000-000000000034', 'Management requires stopping the corticosteroid and treating with an appropriate antifungal (topical for localised disease, oral for extensive, resistant or hair/nail-involving disease).', 3),
('d2000000-0000-0000-0000-000000000035', 'Species identification is critical in cutaneous leishmaniasis because certain New World species (within the Viannia subgenus, common in South/Central America) carry a significant risk of mucocutaneous spread, and require systemic treatment to reduce this risk, in contrast to many Old World species where local therapy may suffice.', 1),
('d2000000-0000-0000-0000-000000000035', 'A non-healing, painless, indurated ulcer at a sandfly bite site in a returning traveller from an endemic area, unresponsive to antibiotics, should prompt biopsy and specific testing for leishmaniasis rather than continued empirical antibacterial treatment.', 2),
('d2000000-0000-0000-0000-000000000035', 'Specialist input is important given the range of systemic treatment options and the need to weigh treatment toxicity against risk of dissemination.', 3),
('d2000000-0000-0000-0000-000000000036', 'IL-17 inhibitors are associated with new-onset or worsening inflammatory bowel disease and should generally be avoided in patients with known IBD.', 1),
('d2000000-0000-0000-0000-000000000036', $x$Anti-TNF agents and IL-23 inhibitors have established efficacy in both psoriasis and Crohn's disease, making them preferred choices when both conditions coexist.$x$, 2),
('d2000000-0000-0000-0000-000000000036', 'Biologic selection in psoriasis should always account for relevant comorbidities (IBD, demyelinating disease favouring avoidance of anti-TNF, heart failure, prior malignancy) rather than skin disease severity alone.', 3),
('d2000000-0000-0000-0000-000000000037', 'Generalised pustular psoriasis (von Zumbusch pattern) is a dermatological emergency with significant risk of systemic complications (sepsis, high-output cardiac failure, electrolyte disturbance, acute respiratory distress) and requires inpatient multidisciplinary management.', 1),
('d2000000-0000-0000-0000-000000000037', 'Abrupt withdrawal of systemic corticosteroids is a recognised precipitant of generalised pustular psoriasis flares, so corticosteroids should generally be avoided or very carefully tapered in psoriasis management.', 2),
('d2000000-0000-0000-0000-000000000037', 'Rapid-acting systemic agents (ciclosporin, acitretin, or targeted biologics/IL-36 pathway inhibitors where available) are used to control the acute flare, alongside meticulous supportive care.', 3),
('d2000000-0000-0000-0000-000000000038', 'Conventional synthetic DMARDs such as methotrexate and sulfasalazine are effective for peripheral joint disease in psoriatic arthritis but have not shown efficacy for axial disease, so persistent axial symptoms should prompt consideration of biologic therapy.', 1),
('d2000000-0000-0000-0000-000000000038', 'Anti-TNF agents and IL-17 inhibitors both have robust evidence for efficacy in axial spondyloarthritis/axial psoriatic arthritis, making either an appropriate choice; IL-23 inhibitors have shown less consistent efficacy specifically for axial disease in trials to date.', 2),
('d2000000-0000-0000-0000-000000000038', 'Treatment decisions in psoriatic arthritis should consider the specific disease domains involved (axial, peripheral, enthesitis, dactylitis, skin, nail) as different drug classes have differing efficacy across these domains.', 3),
('d2000000-0000-0000-0000-000000000039', 'Erosive oral lichen planus refractory to topical corticosteroids warrants escalation to systemic therapy given the significant impact on eating/nutrition and quality of life, alongside continued attention to oral hygiene and secondary candidiasis.', 1),
('d2000000-0000-0000-0000-000000000039', 'Long-standing erosive oral lichen planus carries a small but recognised risk of malignant transformation to oral squamous cell carcinoma, so long-term surveillance is required regardless of treatment response.', 2),
('d2000000-0000-0000-0000-000000000039', 'Topical antifungals may be a useful adjunct if secondary candidiasis is present but do not address the underlying erosive lichen planus itself.', 3),
('d2000000-0000-0000-0000-000000000040', 'Pityriasis rubra pilaris classically presents with cephalocaudal spread of erythema, characteristic islands of sparing, follicular hyperkeratotic papules, and a distinctive orange-red waxy palmoplantar keratoderma, distinguishing it clinically from psoriasis despite overlapping erythematous, scaly features.', 1),
('d2000000-0000-0000-0000-000000000040', 'Systemic retinoids (acitretin, or isotretinoin) are considered first-line systemic therapy for PRP, reflecting the disorder of keratinisation underlying the condition, with methotrexate and biologic agents used for refractory cases.', 2),
('d2000000-0000-0000-0000-000000000040', 'Recognising PRP as a distinct entity is important because response to standard psoriasis therapies can differ, and misdiagnosis as psoriasis can lead to inappropriate treatment selection and delay in effective therapy.', 3),
('d2000000-0000-0000-0000-000000000041', 'Sentinel lymph node biopsy is generally offered for melanomas with Breslow thickness at or above 0.8mm (or below 0.8mm with adverse features such as ulceration or high mitotic rate), identifying patients with a clinically significant risk of occult nodal metastasis.', 1),
('d2000000-0000-0000-0000-000000000041', 'Wide local excision margins are guided by Breslow thickness (e.g. 1cm margin for melanoma in situ, wider margins with increasing thickness), and should be performed alongside, not instead of, nodal staging where indicated.', 2),
('d2000000-0000-0000-0000-000000000041', 'Completion lymphadenectomy is no longer routinely performed for all sentinel-node-positive patients following changes in evidence, with many patients now managed with close nodal ultrasound surveillance instead.', 3),
('d2000000-0000-0000-0000-000000000042', 'Targeted BRAF/MEK inhibitor combination therapy achieves rapid, high response rates and is particularly useful in patients with rapidly progressive or symptomatic disease needing swift disease control, while combination immune checkpoint inhibition can offer more durable long-term responses.', 1),
('d2000000-0000-0000-0000-000000000042', 'BRAF inhibitor monotherapy (without a MEK inhibitor) is associated with a higher risk of cutaneous toxicity, including secondary squamous cell carcinomas, due to paradoxical MAPK pathway activation, so combination BRAF/MEK inhibition is preferred.', 2),
('d2000000-0000-0000-0000-000000000042', 'BRAF mutation testing is essential in metastatic melanoma as it directly determines eligibility for targeted therapy, alongside consideration of immunotherapy.', 3),
('d2000000-0000-0000-0000-000000000043', 'High-risk features for cutaneous SCC recurrence/metastasis include size >2cm, poor differentiation, perineural or lymphovascular invasion, deep invasion, high-risk anatomical sites (central face, ears, lips), and ill-defined clinical margins — such tumours are best managed with Mohs micrographic surgery or complete circumferential peripheral and deep margin assessment.', 1),
('d2000000-0000-0000-0000-000000000043', 'Perineural invasion is an important adverse prognostic marker associated with increased risk of local recurrence and, in more advanced cases, potential need for adjuvant radiotherapy.', 2),
('d2000000-0000-0000-0000-000000000043', 'Destructive or topical treatments (cryotherapy, topical 5-FU, imiquimod) are appropriate for low-risk, superficial lesions but not for high-risk invasive SCC with perineural invasion, where complete histological margin control is essential.', 3),
('d2000000-0000-0000-0000-000000000044', 'Hedgehog pathway inhibitors (vismodegib, sonidegib) are targeted oral therapies licensed for locally advanced or metastatic basal cell carcinoma not amenable to surgery or radiotherapy, exploiting the near-universal dysregulation of the hedgehog signalling pathway in BCC.', 1),
('d2000000-0000-0000-0000-000000000044', 'Common side effects of hedgehog pathway inhibitors include muscle cramps, alopecia, dysgeusia/ageusia, and weight loss, which can affect long-term tolerability and adherence.', 2),
('d2000000-0000-0000-0000-000000000044', 'Anti-PD-1 immunotherapy (e.g. cemiplimab) is a recognised option specifically for patients who have progressed on or are intolerant of hedgehog pathway inhibitor therapy, rather than as routine first-line treatment.', 3),
('d2000000-0000-0000-0000-000000000045', 'Merkel cell carcinoma is a rare, highly aggressive neuroendocrine skin cancer strongly associated with Merkel cell polyomavirus and immunosuppression (e.g. transplant recipients), with a significant propensity for early nodal and distant metastasis.', 1),
('d2000000-0000-0000-0000-000000000045', 'Management of regionally confined disease typically combines surgical excision of the primary with treatment (surgery and/or radiotherapy) of the nodal basin, reflecting the high risk of micrometastatic spread even with a single clinically involved node.', 2),
('d2000000-0000-0000-0000-000000000045', 'Anti-PD-1/PD-L1 immunotherapy has transformed management of advanced/metastatic Merkel cell carcinoma, but immunosuppressed transplant patients require careful multidisciplinary discussion given the competing risk of graft rejection with checkpoint inhibition.', 3),
('d2000000-0000-0000-0000-000000000046', 'Anti-TIF1-gamma (anti-p155/140) antibody positive dermatomyositis carries one of the strongest associations with underlying malignancy among the myositis-specific antibodies, particularly in adults over 40, warranting thorough, often repeated, malignancy screening.', 1),
('d2000000-0000-0000-0000-000000000046', 'Malignancy risk in dermatomyositis is highest in the first 1-2 years around diagnosis, so screening should be prompt rather than delayed, though some guidelines support periodic reassessment for a period afterward given ongoing elevated risk.', 2),
('d2000000-0000-0000-0000-000000000046', 'Myositis-specific antibody profiling provides important prognostic information, including malignancy risk, interstitial lung disease risk (e.g. anti-MDA5, anti-synthetase antibodies), and expected disease course, and should guide the intensity and focus of further work-up.', 3),
('d2000000-0000-0000-0000-000000000047', 'Necrobiosis lipoidica is strongly associated with diabetes mellitus but its course does not reliably correlate with glycaemic control, meaning that optimising diabetes management alone should not be relied upon to improve established skin lesions.', 1),
('d2000000-0000-0000-0000-000000000047', $x$Treatment of active, inflamed lesions typically involves potent topical or intralesional corticosteroids at the advancing border, used cautiously given the lesions' inherent tendency towards atrophy; other options for refractory disease include phototherapy or systemic agents.$x$, 2),
('d2000000-0000-0000-0000-000000000047', 'Ulceration is a recognised complication, often precipitated by minor trauma given the atrophic, fragile overlying skin, so protective measures and wound care are important components of management.', 3),
('d2000000-0000-0000-0000-000000000048', 'Pyoderma gangrenosum characteristically demonstrates pathergy, whereby trauma (including surgical debridement or biopsy) can trigger new lesions or worsen existing ones — surgical intervention should therefore be avoided or minimised.', 1),
('d2000000-0000-0000-0000-000000000048', 'Systemic immunosuppression (corticosteroids as initial treatment, with ciclosporin or biologic agents such as anti-TNF therapy for refractory disease or coexisting IBD) is the mainstay of treatment, addressing the underlying neutrophilic inflammatory process rather than treating it as an infective or surgical wound problem.', 2),
('d2000000-0000-0000-0000-000000000048', 'Because pyoderma gangrenosum is frequently associated with underlying systemic disease (IBD, myeloproliferative disorders, rheumatoid arthritis), identifying and where relevant treating this can also help control cutaneous disease activity.', 3),
('d2000000-0000-0000-0000-000000000049', 'Warfarin is a recognised risk factor for calciphylaxis (calcific uraemic arteriolopathy) as it inhibits vitamin K-dependent matrix Gla protein, an inhibitor of vascular calcification, so it should be discontinued and an alternative anticoagulation strategy considered if still needed.', 1),
('d2000000-0000-0000-0000-000000000049', 'Sodium thiosulfate is used in calciphylaxis for its calcium-chelating and antioxidant properties, alongside correction of hyperphosphataemia/hypercalcaemia and, where relevant, management of hyperparathyroidism, as part of a multimodal approach.', 2),
('d2000000-0000-0000-0000-000000000049', 'Calciphylaxis carries a high mortality, largely driven by sepsis from infected, non-healing ulcers, so aggressive wound care, infection surveillance and effective analgesia are essential alongside disease-specific treatment.', 3),
('d2000000-0000-0000-0000-000000000050', 'Lupus pernio is a distinctive, chronic form of cutaneous sarcoidosis affecting the nose, cheeks and ears with violaceous, indurated plaques; it is strongly associated with chronic, often fibrotic pulmonary sarcoidosis and upper respiratory tract involvement, and tends to be more treatment-resistant than other cutaneous sarcoid manifestations.', 1),
('d2000000-0000-0000-0000-000000000050', 'Non-caseating granulomas on biopsy, combined with bilateral hilar lymphadenopathy and pulmonary infiltrates, support a diagnosis of sarcoidosis over mimics such as lupus erythematosus, rosacea, granulomatosis with polyangiitis or tuberculosis, which have differing histological and clinical features.', 2),
('d2000000-0000-0000-0000-000000000050', 'Given cosmetic disfigurement, risk of nasal/airway compromise and pulmonary involvement, systemic therapy (corticosteroids first-line, with methotrexate or other steroid-sparing agents for chronic/relapsing disease) is warranted rather than topical treatment alone, which is typically inadequate for lupus pernio.', 3);
